CString CLoadCombCtrl::Get_StaticLoadCaseName(int iKey)
{
    T_STLD_D rData;
    rData.Initialize();
    BOOL bCheck = m_pDoc->m_pAttrCtrl->GetStld(iKey,rData);
    ASSERT(bCheck);
    return rData.LoadCaseName;
}

CString CLoadCombCtrl::Get_SpectrumLoadCaseName(int iKey, const CString& strType)
{
    if (strType == _T("ESP"))
    {
        T_SPLC_D rData;
        rData.Initialize();
        BOOL bCheck = m_pDoc->m_pAttrCtrl->GetSplc(iKey,rData);
        ASSERT(bCheck);
        return rData.LoadCaseName;
    }
    else if (strType == _T("ESPE"))
    {
        T_NSPC_D rData;
        rData.Initialize();
        BOOL bCheck = m_pDoc->m_pAttrCtrl->GetNspc(iKey,rData);
        ASSERT(bCheck);
        return _T("N") + rData.LoadCaseName;
    }
    ASSERT(0);
    return _T("-");    
}

CString CLoadCombCtrl::Get_SettlementLoadCaseName(int iKey)
{
    T_SMLC_D rData;
    rData.Initialize();
    BOOL bCheck = m_pDoc->m_pAttrCtrl->GetSmlc(iKey,rData);
    ASSERT(bCheck);
    return rData.LoadCaseName;
}

CString CLoadCombCtrl::Get_MovingLoadLoadCaseName(int iKey)
{
    // 코드에 따른 방식으로 수정 
    T_MVCD_D DataMvcd; DataMvcd.Initialize();
    if (!m_pDoc->m_pAttrCtrl->GetMvcd(DataMvcd)) DataMvcd.Initialize();

    CArray<UINT, UINT> KeyList; KeyList.RemoveAll();
    switch (DataMvcd.nCodeType)
    {
        case D_MOVE_CODE_NONE:
            break;
        case D_MOVE_CODE_AASHTO_STAN:
        case D_MOVE_CODE_AASHTO_LRFD:
        case D_MOVE_CODE_TAIWAN:
        case D_MOVE_CODE_KOREA:
        case D_MOVE_CODE_CANADA:
        case D_MOVE_CODE_PENDOT:
        case D_MOVE_CODE_EURO_BS:
        case D_MOVE_CODE_RUSSIA:
        case D_MOVE_CODE_KOREA_LRFD_2011:
        case D_MOVE_CODE_AUSTRALIA:
        case D_MOVE_CODE_POLAND:
        case D_MOVE_CODE_SOUTH_AFRICA:
        case D_MOVE_CODE_JAPAN_RAIL:
        case D_MOVE_CODE_NEWZEALAND:
        case D_MOVE_CODE_BRAZIL:
            m_pDoc->m_pAttrCtrl->GetMvldKeyList(KeyList);
            break;
        case D_MOVE_CODE_CHINA:
            m_pDoc->m_pAttrCtrl->GetMvldchKeyList(KeyList);
            break;
        case D_MOVE_CODE_JAPAN:
            m_pDoc->m_pAttrCtrl->GetMvldjpKeyList(KeyList);
            break;
        case D_MOVE_CODE_INDIA:
            m_pDoc->m_pAttrCtrl->GetMvldidKeyList(KeyList);
            break;
        case D_MOVE_CODE_BS:
            m_pDoc->m_pAttrCtrl->GetMvldbsKeyList(KeyList);
            break;
		case D_MOVE_CODE_FRANCE:
			m_pDoc->m_pAttrCtrl->GetMvldfrKeyList(KeyList);
			break;
        case D_MOVE_CODE_TRANS:
            m_pDoc->m_pAttrCtrl->GetMvldtrKeyList(KeyList);
            break;
        default:
            ASSERT(0);
            break;
    }

    CString strLoadCase = _T("");
    int nMV = KeyList.GetSize();
    for (int i=0; i<nMV; i++)
    {
        UINT MvKey = KeyList.GetAt(i);
        if (MvKey == iKey)
        {
            T_MVLD_D rData; rData.Initialize();
            T_MVLDjp_D rDatajp; m_pDoc->m_pAttrCtrl->InitializeMvldjp(rDatajp);
            T_MVLDch_D rDatach; rDatach.Initialize();
            T_MVLDid_D rDataid; rDataid.Initialize();
            T_MVLDbs_D rDatabs; rDatabs.Initialize();
			T_MVLDfr_D rDatafr; rDatafr.Initialize();
            T_MVLDtr_D rDatatr; rDatatr.Initialize();

            switch (DataMvcd.nCodeType)
            {
                case D_MOVE_CODE_NONE:
                    break;
                case D_MOVE_CODE_AASHTO_STAN:
                case D_MOVE_CODE_AASHTO_LRFD:
                case D_MOVE_CODE_TAIWAN:
                case D_MOVE_CODE_KOREA:
                case D_MOVE_CODE_CANADA:
                case D_MOVE_CODE_PENDOT:
                case D_MOVE_CODE_EURO_BS:
                case D_MOVE_CODE_RUSSIA:
                case D_MOVE_CODE_KOREA_LRFD_2011:
                case D_MOVE_CODE_AUSTRALIA:
                case D_MOVE_CODE_POLAND:
                case D_MOVE_CODE_SOUTH_AFRICA:
                case D_MOVE_CODE_JAPAN_RAIL:
                case D_MOVE_CODE_NEWZEALAND:
                case D_MOVE_CODE_BRAZIL:
                {
                    if (!m_pDoc->m_pAttrCtrl->GetMvld(KeyList.GetAt(i), rData)) ASSERT(0);
                    strLoadCase = rData.LoadCaseName;
                }
                break;
                case D_MOVE_CODE_CHINA:
                {
                    if (!m_pDoc->m_pAttrCtrl->GetMvldch(KeyList.GetAt(i), rDatach)) ASSERT(0);
                    strLoadCase = rDatach.LoadCaseName;
                }
                break;
                case D_MOVE_CODE_JAPAN:
                {
                    if (!m_pDoc->m_pAttrCtrl->GetMvldjp(KeyList.GetAt(i), rDatajp)) ASSERT(0);
                    strLoadCase = rDatajp.LoadCaseName;
                }
                break;
                case D_MOVE_CODE_INDIA:
                {
                    if (!m_pDoc->m_pAttrCtrl->GetMvldid(KeyList.GetAt(i), rDataid)) ASSERT(0);
                    strLoadCase = rDataid.LoadCaseName;
                }
                break;
                case D_MOVE_CODE_BS:
                {
                    if (!m_pDoc->m_pAttrCtrl->GetMvldbs(KeyList.GetAt(i), rDatabs)) ASSERT(0);
                    strLoadCase = rDatabs.LoadCaseName;
                }
                break;
				case D_MOVE_CODE_FRANCE:
				{
					if (!m_pDoc->m_pAttrCtrl->GetMvldfr(KeyList.GetAt(i), rDatafr)) ASSERT(0);
					strLoadCase = rDatabs.LoadCaseName;
				}
				break;
                case D_MOVE_CODE_TRANS:
                {
                    if (!m_pDoc->m_pAttrCtrl->GetMvldtr(KeyList.GetAt(i), rDatatr)) ASSERT(0);
                    strLoadCase = rDatatr.LoadCaseName;
                }
                break;
                default:
                    ASSERT(0);
                    break;
            }
            break;
        }
    }

    return strLoadCase;
}


