void CLoadCombCtrl::Set_ScaleUpData(CMap<int,int,double,double>& arScaleData)
{
    int nKey=0;
    double dData=0.0;
    if(m_ScaleData.GetCount() != 0) m_ScaleData.RemoveAll();
    POSITION pos;
    for(pos=arScaleData.GetStartPosition(); pos!=NULL;)
    {
        arScaleData.GetNextAssoc(pos,nKey,dData);
        m_ScaleData.SetAt(nKey,dData);
    }
}

BOOL CLoadCombCtrl::Get_ScaleUpFactor(int nLoadCaseType, int iKey, double& dFactor)
{
    dFactor = 1.0;

    if ( m_bModeUG )
    {
        auto itr = m_ScaleDataUG.find(TYPE_LCAS_K(nLoadCaseType, iKey));
        if ( itr != m_ScaleDataUG.end() )
        {
            dFactor = itr->second;
            return TRUE;
        }
        return FALSE;        
    }
    else
    {
        switch ( nLoadCaseType )
        {
        case D_LOADCASE_STATIC:
            {
                return TRUE;
            }            
        case D_LOADCASE_SPECTRUM:
            {
                BOOL bCheck=FALSE;
                bCheck = m_ScaleData.Lookup(iKey, dFactor);
                return bCheck; 
            }
        default:
            {
                ASSERT(0);
                return FALSE;
            }
        }        
    }   
}

