void CLoadCombCtrl::RemoveDuplicateLcom(CArray<T_LCOM_D, T_LCOM_D&>& arLcomD)
{
    // 하중조합 성분이 동일한 조합을 거르도록 처리.
    CArray<T_LCOM_D, T_LCOM_D&> TempLcomCopy; TempLcomCopy.RemoveAll();
    TempLcomCopy.Copy(arLcomD);
    arLcomD.RemoveAll();
    for (int nLc = 0; nLc < TempLcomCopy.GetSize(); nLc++)
    {
        BOOL bSame = FALSE;
        T_LCOM_D CurLcomD = TempLcomCopy[nLc];
        for (int k = 0; k < arLcomD.GetSize(); k++)
        {
            T_LCOM_D PreLcomD = arLcomD[k];
            if (IsSameLcomData(CurLcomD, PreLcomD))
            {
                bSame = TRUE;
                break;
            }
        }

        if (!bSame)  
        {
            CurLcomD.LoadCombId = arLcomD.GetSize() + 1;
            arLcomD.Add(CurLcomD);
        }
    }
}

