BOOL CLoadCombCtrl::Make_LCB_Makelcb_EL(int& LC_No1, int& LC_No2, CString& strReport, double dFac, CombBase& cLoad, CArray<T_LCOM_D,T_LCOM_D&>& arData)
{
    const INT_PTR nSize = cLoad.m_arLd.GetSize();
    if ( nSize == 0 ) { return FALSE; }

    m_mAddUGEP.clear();

    T_LCOM_D rData; 
    rData.Initialize(); 

    const CString& strLcasType = cLoad.Get_Type();

    int arSize = arData.GetSize();
    if(arSize > 0)
    {
        for ( INT_PTR h=0; h<arSize; ++h )
        {
            rData = arData.GetAt(0);
            arData.RemoveAt(0);
            CString strInitDescript = rData.Description;

            for( INT_PTR j=0; j<nSize; ++j)
            {
                const int nSeisLcasK = cLoad.m_arLd.GetAt(j);
                // Add by ZINU.('05.06.16). For Special.
                double dOmega = 1.0;
                // Change by ZINU.('05.07.27). Add m_bUseOmega.
                if ( m_iSetLcomForKBC==1 || m_bUseOmega )
                {
                    if ( !m_arSlcfStldK.Lookup(nSeisLcasK, dOmega) ) { dOmega = 1.0; }
                    Get_RealLcaseFactor(dOmega, _T("OMG"), strInitDescript);
                }

                CString strTemp = strInitDescript;
                double dSUFactor = 0.0;
                Get_ScaleUpFactor(D_LOADCASE_STATIC, nSeisLcasK, dSUFactor);
                if ( m_bModeUG )
                {
                    Get_RealLcaseFactor(dSUFactor, _T("SUF"), strTemp);
                }                

                double dRF = 1.0;
                if ( m_bRedundancyFact )
                {
                    dRF = m_dRedundancyFact;
                    Get_RealLcaseFactor(dRF, _T("RF"), strTemp);
                }

                const double dFactSeis   = dFac*dRF*dOmega*dSUFactor;
                const double dFactSeisEP = dFac*dRF*dOmega; // 지진토압 하중조합 계수는 Scale Up Factor를 고려하지 않음.
                const double dFactStatEP = dFac*dRF;        // 정적토압 하중조합 계수는 Scale Up Factor 및 Over Strength Factor를 고려하지 않음.
                
                const CString& strLcName =	Get_StaticLoadCaseName(nSeisLcasK);
                Set_WindOrEqCase(nSeisLcasK, dFactSeis, LC_No1, rData);
                
                if ( strLcasType == _T("EL") )
                {
                    Get_RealLcaseName(_T("EL"), strLcName, strTemp); //EP까지 바뀔우려때문         
                }
                else if ( strLcasType == _T("EE") )
                {
                    Get_RealLcaseName(_T("EE"), strLcName, strTemp); //EP까지 바뀔우려때문         
                }
                rData.Description = strTemp;

                if ( m_bModeUG )
                {
                    rData.nSeisLcomType = -1; /// nSeisLcomType을 토압 map의 KEY로 사용할 거라 -1로 초기화.
                }

                std::vector<T_LCOM_BASE> vUGEP;                
                if ( GetLcomBaseListUGEP(D_LOADCASE_STATIC, nSeisLcasK, dFactStatEP, dFactSeisEP, vUGEP) > 0 )
                {
                    rData.nSeisLcomType = arData.GetSize();
                    m_mAddUGEP.insert(std::make_pair(rData.nSeisLcomType, vUGEP));
                }
                                
                arData.Add(rData);
                // Add by ZINU.('05.04.25). Consider SRSS.
                if(m_iSetLcomForSRSS==1)	// 1st Lcom For SRSS.
                {
                    // Coded by Seungjun MNet:No.2516 ('20061017)
                    GetLcomOrthoForSRSS((unsigned int)cLoad.m_arLd.GetAt(j), (unsigned int)cLoad.Get_CaseType());
                }
            }
            rData.Initialize();
        }
    }
    else
    {
        for( INT_PTR j=0; j<nSize; ++j)
        {
            CString strTemp = strReport; 
            const int nSeisLcasK = cLoad.m_arLd.GetAt(j);
            // Add by ZINU.('05.06.16). For Special.
            double dOmega=1.0;
            // Change by ZINU.('05.07.27). Add m_bUseOmega
            if(m_iSetLcomForKBC==1 || m_bUseOmega)
            {
                if(!m_arSlcfStldK.Lookup(nSeisLcasK, dOmega))	dOmega = 1.0;
                Get_RealLcaseFactor(dOmega, _T("OMG"), strTemp);
            }

            double dSUFactor = 0.0;
            Get_ScaleUpFactor(D_LOADCASE_STATIC, nSeisLcasK, dSUFactor);
            if ( m_bModeUG )
            {
                Get_RealLcaseFactor(dSUFactor, _T("SUF"), strTemp);
            }            

            double dRF = 1.0;
            if ( m_bRedundancyFact )
            {
                dRF = m_dRedundancyFact;
                Get_RealLcaseFactor(dRF, _T("RF"), strTemp);
            }
            
            const double dFactSeis = dFac*dRF*dOmega*dSUFactor;

            CString strLcName =	Get_StaticLoadCaseName(cLoad.m_arLd.GetAt(j));
            Set_WindOrEqCase(cLoad.m_arLd.GetAt(j), dFactSeis, LC_No1, rData);
            //CString strTemp = strReport;
            if      (strLcasType == _T("EL")) Get_RealLcaseName(_T("EL"), strLcName, strTemp); //EP까지 바뀔우려때문
            else if (strLcasType == _T("EE")) Get_RealLcaseName(_T("EE"), strLcName, strTemp); //EP까지 바뀔우려때문
            rData.Description = strTemp;
                        
            arData.Add(rData);
            // Add by ZINU.('05.04.25). Consider SRSS.
            if(m_iSetLcomForSRSS==1)	// 1st Lcom For SRSS.
            {
                /*
                _LCOM_ORTHO LcomOrtho;
                if(m_arLcomOrtho.Lookup((unsigned int)cLoad.m_arLd.GetAt(j),LcomOrtho))	m_arLcomOrthoSort.Add(LcomOrtho);
                */
                // Coded by Seungjun MNet:No.2516 ('20061017)
                GetLcomOrthoForSRSS((unsigned int)cLoad.m_arLd.GetAt(j), (unsigned int)cLoad.Get_CaseType());
            }
        }
        rData.Initialize();
    }
    LC_No2 = LC_No1 +1;
    LC_No1++;

    return TRUE;
}

