    Set_LCB( nA, _T("1.0DL + 1.4EL + PS"),  1.0,cDL,1.0,cCSD,   1.4,cEL,    1.0,cPS );
    Set_LCB( nA, _T("1.0DL - 1.4EL + PS"),  1.0,cDL,1.0,cCSD,  -1.4,cEL,    1.0,cPS );

    Set_LCB( nA, _T("1.2DL + 1.2(LL+LR) + 1.2(SUF)ESP + PS"),   1.2,cDL,1.2,cCSD,   1.2,cLL,1.2,cCSL,   1.2,cLR,    1.2,cESP,   1.0,cPS );
    Set_LCB( nA, _T("1.2DL + 1.2(LL+LR) - 1.2(SUF)ESP + PS"),   1.2,cDL,1.2,cCSD,   1.2,cLL,1.2,cCSL,   1.2,cLR,   -1.2,cESP,   1.0,cPS );
