            Set_LCB(nA+1, _T("DL + (LL+LR) + WL + (SFAC)TS"),				dSF,cDL,dSF,cCSD,				dSF, cLL,dSF, cCSL,	dSF,cLR,			  dSF, cWL, dPSS,cTS  );
            Set_LCB(nA+1, _T("DL + (LL+LR) - WL + (SFAC)TS"),				dSF,cDL,dSF,cCSD,			  dSF, cLL,	dSF, cCSL,dSF,cLR, (-1.0)*dSF, cWL, dPSS,cTS						);
