        Set_LCB(nA, _T("1.4DL + 1.5FP + (SFAC)PS"),  													1.4, cDL,1.4, cCSD,  1.5,	 cFP,                                                  dPSS, cPS	);
        Set_LCB(nA, _T("0.9DL + 1.5FP + (SFAC)PS"),  													0.9, cDL,0.9, cCSD,  1.5,	 cFP,                                                  dPSS, cPS	);

