            Set_LCB(nA+1, _T("(DL + (LL+LR) + WL)/1.5 + (SFAC)PS"),			 dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR,		 		 dSF,cWL,	 dPSS,cPS);
            Set_LCB(nA+1, _T("(DL + (LL+LR) - WL)/1.5 + (SFAC)PS"),			 dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR,	(-1.0)*dSF,cWL,  dPSS,cPS);
