            Set_LCB(nA+1, _T("(DL - WL)/1.5 + (SFAC)PS"),								 dSF,cDL,dSF,cCSD,	(-1.0)*dSF, cWL, 													 dPSS,cPS);
            Set_LCB(nA+1, _T("(DL + (LL+LR) + EL)/1.5 + (SFAC)PS"),			 dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR,				 dSF,cEL,  dPSS,cPS);
            Set_LCB(nA+1, _T("(DL + (LL+LR) - EL)/1.5 + (SFAC)PS"),			 dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR,	(-1.0)*dSF,cEL,  dPSS,cPS);
            Set_LCB(nA+1, _T("(DL + EL)/1.5 + (SFAC)PS"),								 dSF,cDL,dSF,cCSD,				 dSF, cEL, 													 dPSS,cPS);
            Set_LCB(nA+1, _T("(DL - EL)/1.5 + (SFAC)PS"),								 dSF,cDL,dSF,cCSD,	(-1.0)*dSF, cEL, 													 dPSS,cPS);
            Set_LCB(nA+1, _T("(DL + (LL+LR) + (SUF)ESP)/1.5 + (SFAC)PS"),dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR,				 dSF,cESP, dPSS,cPS);
