                Set_LCB(nA+4, _T("1.2DL + 1.3WL + 1.0LL + 0.5LR + (SFAC)TS"),	1.2,cDL,1.2,cCSD, 1.3,cWL, 1.0,cLL,1.0,cCSL, 0.5,cLR, dPSS,cTS	);
                Set_LCB(nA+4, _T("1.2DL - 1.3WL + 1.0LL + 0.5LR + (SFAC)TS"),	1.2,cDL,1.2,cCSD,-1.3,cWL, 1.0,cLL,1.0,cCSL, 0.5,cLR, dPSS,cTS	);
                Set_LCB(nA+4, _T("1.2DL + 1.3WL + 1.0LL + 0.5SL + (SFAC)TS"),	1.2,cDL,1.2,cCSD, 1.3,cWL, 1.0,cLL,1.0,cCSL, 0.5,cSL, dPSS,cTS	);
                Set_LCB(nA+4, _T("1.2DL - 1.3WL + 1.0LL + 0.5SL + (SFAC)TS"),	1.2,cDL,1.2,cCSD,-1.3,cWL, 1.0,cLL,1.0,cCSL, 0.5,cSL, dPSS,cTS	);
                Set_LCB(nA+4, _T("1.2DL + 1.3WL + 1.0LL + 0.5RL + (SFAC)TS"),	1.2,cDL,1.2,cCSD, 1.3,cWL, 1.0,cLL,1.0,cCSL, 0.5,cRL, dPSS,cTS	);
                Set_LCB(nA+4, _T("1.2DL - 1.3WL + 1.0LL + 0.5RL + (SFAC)TS"),	1.2,cDL,1.2,cCSD,-1.3,cWL, 1.0,cLL,1.0,cCSL, 0.5,cRL, dPSS,cTS	);
