                    Set_LCB(nA+4, _T("0.9DL - 1.0EL + (SFAC)TS"),			  0.9,cDL,0.9,cCSD,-1.0,cEL,  dPSS,cTS);
                    Set_LCB(nA+4, _T("0.9DL + 1.0(SUF)ESP + (SFAC)TS"), 0.9,cDL,0.9,cCSD, 1.0,cESP, dPSS,cTS);
                    Set_LCB(nA+4, _T("0.9DL - 1.0(SUF)ESP + (SFAC)TS"), 0.9,cDL,0.9,cCSD,-1.0,cESP, dPSS,cTS);
