        Set_LCB(nA  , _T("0.75(1.4DL + 1.7(LL+LR)) - 1.0EL + (SFAC)PS"),				1.05,cDL,1.05,cCSD,  1.275,cLL,1.275,cCSL,		1.275,cLR,  -1.0,  cEL,                        dPSS, cPS	);
