        Set_LCB(nA  , _T("0.75(1.4DL + 1.7(LL+LR)) + 1.0(SUF)ESP + (SFAC)PS"),	1.05,cDL,1.05,cCSD,  1.275,cLL,1.275,cCSL,		1.275,cLR,   1.0,  cESP,                       dPSS, cPS	);
        Set_LCB(nA  , _T("0.75(1.4DL + 1.7(LL+LR)) - 1.0(SUF)ESP + (SFAC)PS"),	1.05,cDL,1.05,cCSD,  1.275,cLL,1.275,cCSL,		1.275,cLR,  -1.0,  cESP,                       dPSS, cPS	);
        Set_LCB(nA-1, _T("0.75(1.4DL) + 1.0(SUF)ESP + (SFAC)PS"),					 	 		1.05,cDL,1.05,cCSD,  1.0,  cESP,																								 dPSS, cPS	);
        Set_LCB(nA-1, _T("0.75(1.4DL) - 1.0(SUF)ESP + (SFAC)PS"),					 	 		1.05,cDL,1.05,cCSD, -1.0,  cESP,																								 dPSS, cPS	);
        Set_LCB(nA  , _T("0.9DL + 1.0(SUF)ESP + (SFAC)PS"),								 			0.9, cDL,0.9, cCSD,  1.0,	 cESP,                                                 dPSS, cPS  );
        Set_LCB(nA  , _T("0.9DL - 1.0(SUF)ESP + (SFAC)PS"),											0.9, cDL,0.9, cCSD, -1.0,	 cESP,																								 dPSS, cPS  );
        Set_LCB(nA  , _T("0.75(1.4DL + 1.7(LL+LR) + 1.5(TL+CR+SH)) + (SFAC)PS"),1.05,cDL,1.05,cCSD,  1.275,cLL,	1.275,cCSL,	1.275,cLR,	 1.125,cTL,	 1.125,cCR, 1.125,cSH, 1.125,cCSC, 1.125,cCSS,dPSS, cPS	);
