            Set_LCB(nA+1, _T("DL + WL + (SFAC)PS"),											dSF,cDL,dSF,cCSD,				 dSF, cWL, 													 dPSS,cPS);
            Set_LCB(nA+1, _T("DL - WL + (SFAC)PS"),											dSF,cDL,dSF,cCSD,	(-1.0)*dSF, cWL, 													 dPSS,cPS);
            Set_LCB(nA+1, _T("DL + (LL+LR) + 0.7*EL + (SFAC)PS"),				dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR, ( 0.7)*dSF,cEL,  dPSS,cPS);
            Set_LCB(nA+1, _T("DL + (LL+LR) - 0.7*EL + (SFAC)PS"),				dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR, (-0.7)*dSF,cEL,  dPSS,cPS);
            Set_LCB(nA+1, _T("DL + 0.7*EL + (SFAC)PS"),									dSF,cDL,dSF,cCSD,	( 0.7)*dSF, cEL, 													 dPSS,cPS);
            Set_LCB(nA+1, _T("DL - 0.7*EL + (SFAC)PS"),									dSF,cDL,dSF,cCSD,	(-0.7)*dSF, cEL, 													 dPSS,cPS);
            Set_LCB(nA+1, _T("DL + (LL+LR) + 0.7*(SUF)ESP + (SFAC)PS"), dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR,	( 0.7)*dSF,cESP, dPSS,cPS);
            Set_LCB(nA+1, _T("DL + (LL+LR) - 0.7*(SUF)ESP + (SFAC)PS"), dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR,	(-0.7)*dSF,cESP, dPSS,cPS);
