            dSF = 1.0/1.5;
            Set_LCB(nA+1, _T("DL + (LL+LR) + (SFAC)PS"),											1.0,cDL,1.0,cCSD,				 1.0, cLL,1.0, cCSL, 1.0,cLR,									 dPSS,cPS);
            Set_LCB(nA+1, _T("(DL + (LL+LR) + WL)/1.5 + (SFAC)PS"),						dSF,cDL,dSF,cCSD,				 dSF, cLL,dSF, cCSL, dSF,cLR,		 		 dSF,cWL,	 dPSS,cPS);
