            Set_LCB(nA+3, _T("0.9DL - 1.0(OMG)EL + (SFAC)TS - (SPC)(SDS)DL"),									 			 		dDL9,cDL,dDL9,cCSD, -1.0,	 cEL,                                                  dPSS, cTS	);
            Set_LCB(nA+3, _T("0.75(1.4DL + 1.7(LL+LR)) + 1.0(SUF)(OMG)ESP + (SFAC)TS + (SPC)(SDS)DL"),	dDLp,cDL,dDLp,cCSD,  1.275,cLL,1.275,cCSL,		1.275,cLR,   1.0, cESP,            dPSS, cTS	);
