            Set_LCB(nA+4, _T("0.9DL + 1.7(LL+LR) + 1.5FP + (SFAC)PS"),  						0.9, cDL,0.9, cCSD,  1.7,	 cLL,1.7,	 cCSL,   1.7,  cLR,   1.5,	 cFP,                        dPSS, cPS	);
            Set_LCB(nA+4, _T("1.5DL + 1.5FP + (SFAC)PS"),  													1.5, cDL,1.5, cCSD,  1.5,	 cFP,                                                  dPSS, cPS	);
            Set_LCB(nA+4, _T("0.9DL + 1.5FP + (SFAC)PS"),  													0.9, cDL,0.9, cCSD,  1.5,	 cFP,                                                  dPSS, cPS	);
