// Coded by Seungjun MNet:No.2393 ('20060925)
void CLoadCombCtrl::MakeSRCComb_KBC_SRC05(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL, CombBase* cSL,
                                          CombBase* cRL, CombBase* cIP, CombBase* cTL, CombBase* cSH, CombBase* cCR, CombBase* cWP, 
                                          CombBase* cEP, CombBase* cFP, CombBase* cPS, CombBase* cESP,  CombBase* cCSD, CombBase* cCSL)
{
    double dSF = 1.0/1.5;

    int nA = 1 + m_nConstLoad*100;
    SetCombBaseConsiderCS(m_nConstLoad, &cDL, &cCSD, &cLL, &cCSL);

    SetAddSeisLcomParam();

    m_iSetLcomForKBC = 0;

    // Add by ZINU.('06.07.28). NO:2341, For Calculation Sheet.
    if(m_nLcomType==D_LCOMTYPE_GENERAL)	Make_LCB_OnlyRespEccn(nA, cESP);

    // for SRSS  
    Set_PrevLcomSRSS(FALSE,1.0,1.0, cEL, cESP);

    double dEL = dSF*0.7;

    Set_LCB( nA, _T("DL + (LL+LR) + PS"),            1.0,cDL,1.0,cCSD, 1.0,cLL,1.0,cCSL, 1.0,cLR, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) + WL)/1.5 + PS"), dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL, dSF,cLR,		 dSF,cWL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) - WL)/1.5 + PS"), dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL, dSF,cLR, (-1.0)*dSF,cWL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + WL)/1.5 + PS"),			 dSF,cDL,dSF,cCSD,        dSF,cWL, 1.0,cPS );
    Set_LCB( nA, _T("(DL - WL)/1.5 + PS"),			 dSF,cDL,dSF,cCSD, (-1.0)*dSF,cWL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) + 0.7EL)/1.5 + PS"), dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL,	dSF,cLR,		dEL,cEL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) - 0.7EL)/1.5 + PS"), dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL,	dSF,cLR, (-1.0)*dEL,cEL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + 0.7EL)/1.5 + PS"),			dSF,cDL,dSF,cCSD,		 dEL,cEL, 1.0,cPS );
    Set_LCB( nA, _T("(DL - 0.7EL)/1.5 + PS"),			dSF,cDL,dSF,cCSD, (-1.0)*dEL,cEL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) + 0.7(SUF)ESP)/1.5 + PS"),	dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL,	dSF,cLR,		dEL,cESP,1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) - 0.7(SUF)ESP)/1.5 + PS"),	dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL,	dSF,cLR, (-1.0)*dEL,cESP,1.0,cPS );
    Set_LCB( nA, _T("(DL + 0.7(SUF)ESP)/1.5 + PS"),				dSF,cDL,dSF,cCSD,		 dEL,cESP, 1.0,cPS );
    Set_LCB( nA, _T("(DL - 0.7(SUF)ESP)/1.5 + PS"),				dSF,cDL,dSF,cCSD, (-1.0)*dEL,cESP, 1.0,cPS );


    // Coded by Seungjun MNet:No.2393 ('20060925)
    if(m_bSlcmSpecial)
    {
        dSF = 1./1.7;
        dEL = dSF*0.7;
        m_iSetLcomForKBC = 1;
        Set_PrevLcomSRSS(TRUE,1.,1., cEL,cESP);
        double dDLp = dSF*(1.0 + 0.7 * m_dSlcmSds * m_dSlcmSpecial);
        double dSF1 = 1.0/1.5;

        Set_LCB(nA+3, _T("DL + (LL+LR) + PS"),							 	                             1.0,cDL, 1.0,cCSD,1.0,cLL,1.0,cCSL,1.0,cLR,									                            1.0,cPS	);
        Set_LCB(nA+3, _T("(DL + (LL+LR) + WL)/1.5 + PS"),			                            dSF1,cDL,dSF1,cCSD,dSF1,cLL,dSF1,cCSL,dSF1,cLR,			 dSF1,cWL,		                            1.0,cPS	);
        Set_LCB(nA+3, _T("(DL + (LL+LR) - WL)/1.5 + PS"),			                            dSF1,cDL,dSF1,cCSD,dSF1,cLL,dSF1,cCSL,dSF1,cLR,(-1.0)*dSF1,cWL,		                            1.0,cPS	);
        Set_LCB(nA+3, _T("(DL + WL)/1.5 + PS"),								                            dSF1,cDL,dSF1,cCSD,                                dSF1,cWL,															  1.0,cPS	);
        Set_LCB(nA+3, _T("(DL - WL)/1.5 + PS"),								                            dSF1,cDL,dSF1,cCSD,                         (-1.0)*dSF1,cWL,															  1.0,cPS	);
		Set_LCB(nA+3, _T("(DL + (LL+LR) + 0.7(OMG)EL + 0.7(SPC)(SDS)DL)/1.7 + PS"), dDLp, cDL, dDLp, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dEL, cEL, 1.0, cPS);
		Set_LCB(nA+3, _T("(DL + (LL+LR) - 0.7(OMG)EL + 0.7(SPC)(SDS)DL)/1.7 + PS"), dDLp, cDL, dDLp, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, (-1.0)*dEL, cEL, 1.0, cPS);
		Set_LCB(nA+3, _T("(DL + 0.7(OMG)EL + 0.7(SPC)(SDS)DL)/1.7 + PS"), dDLp, cDL, dDLp, cCSD, dEL, cEL, 1.0, cPS);
		Set_LCB(nA+3, _T("(DL - 0.7(OMG)EL + 0.7(SPC)(SDS)DL)/1.7 + PS"), dDLp, cDL, dDLp, cCSD, (-1.0)*dEL, cEL, 1.0, cPS);
		Set_LCB(nA+3, _T("(DL + (LL+LR) + 0.7(SUF)(OMG)ESP + 0.7(SPC)(SDS)DL)/1.7 + PS"), dDLp, cDL, dDLp, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dEL, cESP, 1.0, cPS);
		Set_LCB(nA+3, _T("(DL + (LL+LR) - 0.7(SUF)(OMG)ESP + 0.7(SPC)(SDS)DL)/1.7 + PS"), dDLp, cDL, dDLp, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, (-1.0)*dEL, cESP, 1.0, cPS);
		Set_LCB(nA+3, _T("(DL + 0.7(SUF)(OMG)ESP + 0.7(SPC)(SDS)DL)/1.7 + PS"), dDLp, cDL, dDLp, cCSD, dEL, cESP, 1.0, cPS);
		Set_LCB(nA+3, _T("(DL - 0.7(SUF)(OMG)ESP + 0.7(SPC)(SDS)DL)/1.7 + PS"), dDLp, cDL, dDLp, cCSD, (-1.0)*dEL, cESP, 1.0, cPS);
    }

    if(m_bSlcmVertical)
    {
        dSF = 1.0/1.5;
        dEL = dSF*0.7;
        m_iSetLcomForKBC = 2;
        Set_PrevLcomSRSS(FALSE,1.,1., cEL,cESP);
        double dDLv = dSF*(-1)*m_dSlcmVertical;

        Set_LCB(nA+4, _T("DL + (LL+LR) + PS"),							 	      1.0,cDL,1.0,cCSD,1.0,cLL,1.0,cCSL,1.0,cLR,									                             1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + (LL+LR) + WL)/1.5 + PS"),           dSF,cDL,dSF,cCSD,dSF,cLL,dSF,cCSL,dSF,cLR,			 dSF,cWL,		                             1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + (LL+LR) - WL)/1.5 + PS"),           dSF,cDL,dSF,cCSD,dSF,cLL,dSF,cCSL,dSF,cLR,(-1.0)*dSF,cWL,		                             1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + WL)/1.5 + PS"),                     dSF,cDL,dSF,cCSD,       		                     dSF,cWL,															   1.0,cPS	);
        Set_LCB(nA+4, _T("(DL - WL)/1.5 + PS"),                     dSF,cDL,dSF,cCSD,                         (-1.0)*dSF,cWL,															   1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + (LL+LR) + 0.7EL)/1.5 + PS"),				    dSF,cDL,dSF,cCSD,dSF,cLL,dSF,cCSL,	dSF,cLR,				dSF,cEL, 1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + (LL+LR) - 0.7EL)/1.5 + PS"),				    dSF,cDL,dSF,cCSD,dSF,cLL,dSF,cCSL,	dSF,cLR, (-1.0)*dSF,cEL, 1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + 0.7EL)/1.5 + PS"),								  dSF,cDL,dSF,cCSD,			                                          dEL,cEL,								 1.0,cPS	);
        Set_LCB(nA+4, _T("(DL - 0.7EL)/1.5 + PS"),								  dSF,cDL,dSF,cCSD,                                        (-1.0)*dEL,cEL,								 1.0,cPS	);
        Set_LCB(nA+4, _T("-(VER)DL + (0.7EL)/1.5 + PS"),			     dDLv,cDL,dSF,cCSD,                               	              dEL,cEL,								 1.0,cPS	);
        Set_LCB(nA+4, _T("-(VER)DL - (0.7EL)/1.5 + PS"),			     dDLv,cDL,dSF,cCSD,                                        (-1.0)*dEL,cEL,								 1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + (LL+LR) + 0.7(SUF)ESP)/1.5 + PS"),	    dSF,cDL,dSF,cCSD,dSF,cLL,dSF,cCSL,	dSF,cLR,				dSF,cESP, 1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + (LL+LR) - 0.7(SUF)ESP)/1.5 + PS"),	    dSF,cDL,dSF,cCSD,dSF,cLL,dSF,cCSL,	dSF,cLR, (-1.0)*dSF,cESP, 1.0,cPS	);
        Set_LCB(nA+4, _T("(DL + 0.7(SUF)ESP)/1.5 + PS"),					  dSF,cDL,dSF,cCSD,                                              dEL,cESP,1.0,cPS	);
        Set_LCB(nA+4, _T("(DL - 0.7(SUF)ESP)/1.5 + PS"),					  dSF,cDL,dSF,cCSD,                                       (-1.0)*dEL,cESP,1.0,cPS	);
        Set_LCB(nA+4, _T("-(VER)DL + (0.7(SUF)ESP)/1.5 + PS"),     dDLv,cDL,dSF,cCSD,	                                             dEL,cESP,1.0,cPS	);
        Set_LCB(nA+4, _T("-(VER)DL - (0.7(SUF)ESP)/1.5 + PS"),     dDLv,cDL,dSF,cCSD,                                       (-1.0)*dEL,cESP,1.0,cPS	);
    }
    // Add by ZINU.('05.04.19). Consider SRSS.
    if(m_nOrthoType==1)	m_iSetLcomForSRSS = 0;
    //fout.close();
}

