    Set_LCB( nA, _T("(DL + (LL+LR) + WL)/1.5 + PS"), dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL, dSF,cLR,		 dSF,cWL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) - WL)/1.5 + PS"), dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL, dSF,cLR, (-1.0)*dSF,cWL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + WL)/1.5 + PS"),			 dSF,cDL,dSF,cCSD,        dSF,cWL, 1.0,cPS );
    Set_LCB( nA, _T("(DL - WL)/1.5 + PS"),			 dSF,cDL,dSF,cCSD, (-1.0)*dSF,cWL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) + EL)/1.5 + PS"), dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL, dSF,cLR,		 dSF,cEL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) - EL)/1.5 + PS"), dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL, dSF,cLR, (-1.0)*dSF,cEL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + EL)/1.5 + PS"),			 dSF,cDL,dSF,cCSD,		  dSF,cEL, 1.0,cPS );
    Set_LCB( nA, _T("(DL - EL)/1.5 + PS"),			 dSF,cDL,dSF,cCSD, (-1.0)*dSF,cEL, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) + (SUF)ESP)/1.5 + PS"),	dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL,	dSF,cLR,		dSF,cESP, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) - (SUF)ESP)/1.5 + PS"),	dSF,cDL,dSF,cCSD, dSF,cLL,dSF,cCSL,	dSF,cLR, (-1.0)*dSF,cESP, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (SUF)ESP)/1.5 + PS"),     dSF,cDL,dSF,cCSD,		  dSF,cESP, 1.0,cPS	);
    Set_LCB( nA, _T("(DL - (SUF)ESP)/1.5 + PS"),     dSF,cDL,dSF,cCSD, (-1.0)*dSF,cESP, 1.0,cPS	);
