void CLoadCombCtrl::MakeSRCComb_TWN_SRC100(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL, CombBase* cSL, CombBase* cRL, CombBase* cIP, CombBase* cTL, CombBase* cSH, CombBase* cCR, CombBase* cWP, CombBase* cEP, CombBase* cFP, CombBase* cPS, CombBase* cESP, 
                                           CombBase* cCSD, CombBase* cCSL, CombBase* cCSC, CombBase* cCSS)
{
    // PMS:4387-PARKHJ-20111020 : TWN-SRC92 와 동일!
    MakeSRCComb_TWN_SRC92(cDL, cLL, cLR, cWL, cEL, cSL, cRL, cIP, cTL, cSH, cCR, cWP, cEP, cFP, cPS, cESP, cCSD, cCSL, cCSC, cCSS);
}

void CLoadCombCtrl::MakeSRCComb_TWN_SRC92(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL, CombBase* cSL, CombBase* cRL, CombBase* cIP, CombBase* cTL, CombBase* cSH, CombBase* cCR, CombBase* cWP, CombBase* cEP, CombBase* cFP, CombBase* cPS, CombBase* cESP, 
                                          CombBase* cCSD, CombBase* cCSL, CombBase* cCSC, CombBase* cCSS)
{
    double dSF  = 1.0;	// Safety Factor.
    int iLcomType = Get_CurrentLoadCombType();
    BOOL bExistLL = IsExistLL(m_nConstLoad, cLL, cCSL);
    SetCombBaseConsiderCS(m_nConstLoad, &cDL, &cCSD, &cLL, &cCSL, &cCR, &cCSC, &cSH, &cCSS);
    int nA = 1 + m_nConstLoad*100;
    
    //1.4D + 1.4 F
    if(cFP->IsExist())
        Set_LCB( nA, _T("1.4DL + 1.4FP + PS"), 1.4,cDL,1.4,cCSD, 1.4,cFP, 1.0,cPS );
    else
        Set_LCB( nA, _T("1.4DL + PS"), 1.4,cDL,1.4,cCSD, 1.0,cPS );

    //1.2(D+F+T) +1.6(L+H) + 0.5(LR or S or R)
    if(!cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist())
    {
        Set_LCB( nA, _T("1.2(DL+FP+(TL+CR+SH)) + 1.6(LL+(EP+WP)) + PS"), 1.2,cDL,1.2,cCSD, 1.2,cFP, 1.2,cTL, 1.2,cCR, 1.2,cSH, 1.2,cCSC, 1.2,cCSS, 1.6,cLL,1.6,cCSL, 1.6,cEP, 1.6,cWP, 1.0,cPS );
    }
    else //(cLR->IsExist() && cSL->IsExist() && cRL->IsExist())	
    {
        Set_LCB( nA, _T("1.2(DL+FP+(TL+CR+SH)) + 1.6(LL+(EP+WP)) + 0.5LR + PS"), 1.2,cDL,1.2,cCSD, 1.2,cFP, 1.2,cTL, 1.2,cCR, 1.2,cSH, 1.2,cCSC, 1.2,cCSS, 1.6,cLL,1.6,cCSL, 1.6,cEP, 1.6,cWP, 0.5,cLR, 1.0,cPS	);
        Set_LCB( nA, _T("1.2(DL+FP+(TL+CR+SH)) + 1.6(LL+(EP+WP)) + 0.5SL + PS"), 1.2,cDL,1.2,cCSD, 1.2,cFP, 1.2,cTL, 1.2,cCR, 1.2,cSH, 1.2,cCSC, 1.2,cCSS, 1.6,cLL,1.6,cCSL, 1.6,cEP, 1.6,cWP, 0.5,cSL, 1.0,cPS	);
        Set_LCB( nA, _T("1.2(DL+FP+(TL+CR+SH)) + 1.6(LL+(EP+WP)) + 0.5RL + PS"), 1.2,cDL,1.2,cCSD, 1.2,cFP, 1.2,cTL, 1.2,cCR, 1.2,cSH, 1.2,cCSC, 1.2,cCSS, 1.6,cLL,1.6,cCSL, 1.6,cEP, 1.6,cWP, 0.5,cRL, 1.0,cPS	);
    }

    //1.2D + 1.6(LR or S or R) + (1.0L or 0.8W)
    if ( !bExistLL && !cWL->IsExist() )
    {
        Set_LCB( nA, _T("1.2DL + 1.6LR + PS"), 1.2,cDL,1.2,cCSD, 1.6,cLR, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6SL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6RL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cRL, 1.0,cPS );
    }
    else
    {
        Set_LCB( nA, _T("1.2DL + 1.6LR + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cLR,  1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6LR + 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cLR,  0.8,cWL,	1.0,cPS	);
        Set_LCB( nA, _T("1.2DL + 1.6LR - 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cLR, -0.8,cWL,	1.0,cPS	);
        Set_LCB( nA, _T("1.2DL + 1.6SL + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cSL,  1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6SL + 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cSL,  0.8,cWL,	1.0,cPS	);
        Set_LCB( nA, _T("1.2DL + 1.6SL - 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cSL, -0.8,cWL,	1.0,cPS	);
        Set_LCB( nA, _T("1.2DL + 1.6RL + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cRL,  1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6RL + 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cRL,  0.8,cWL,	1.0,cPS	);
        Set_LCB( nA, _T("1.2DL + 1.6RL - 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cRL, -0.8,cWL,	1.0,cPS	);
    }

    //1.2D + 1.6W + 1.0L +0.5(LR or S or R)
    if(!bExistLL && !cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist())	
    {		
        Set_LCB( nA, _T("1.2DL + 1.6WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cWL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + PS"), 1.2,cDL,1.2,cCSD,-1.6,cWL, 1.0,cPS );
    }
    else if(!cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist())	
    {		
        Set_LCB( nA, _T("1.2DL + 1.6WL + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cWL, 1.0,cLL,1.0,cCSL, 1.0,cPS	);
        Set_LCB( nA, _T("1.2DL - 1.6WL + 1.0LL + PS"), 1.2,cDL,1.2,cCSD,-1.6,cWL, 1.0,cLL,1.0,cCSL, 1.0,cPS	);
    }
    else if(!cLL->IsExist())
    {		
        Set_LCB( nA, _T("1.2DL + 1.6WL + 0.5LR + PS"), 1.2,cDL,1.2,cCSD, 1.6,cWL, 0.5,cLR, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 0.5LR + PS"), 1.2,cDL,1.2,cCSD,-1.6,cWL, 0.5,cLR, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6WL + 0.5SL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cWL, 0.5,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 0.5SL + PS"), 1.2,cDL,1.2,cCSD,-1.6,cWL, 0.5,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6WL + 0.5RL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cWL, 0.5,cRL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 0.5RL + PS"), 1.2,cDL,1.2,cCSD,-1.6,cWL, 0.5,cRL, 1.0,cPS );
    }
    else
    {		
        Set_LCB( nA, _T("1.2DL + 1.6WL + 1.0LL + 0.5LR + PS"), 1.2,cDL,1.2,cCSD, 1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cLR, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 1.0LL + 0.5LR + PS"), 1.2,cDL,1.2,cCSD,-1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cLR, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6WL + 1.0LL + 0.5SL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 1.0LL + 0.5SL + PS"), 1.2,cDL,1.2,cCSD,-1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6WL + 1.0LL + 0.5RL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cRL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 1.0LL + 0.5RL + PS"), 1.2,cDL,1.2,cCSD,-1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cRL, 1.0,cPS );
    }

    //1.2D + 1.0E + 1.0L + 0.2S		
    if(!bExistLL && !cSL->IsExist())
    {
        Set_LCB( nA, _T("1.2DL + 1.0EL + PS"),		 1.2,cDL,1.2,cCSD,  1.0, cEL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0EL + PS"),		 1.2,cDL,1.2,cCSD, -1.0, cEL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.0(SUF)ESP + PS"), 1.2,cDL,1.2,cCSD,  1.0,cESP, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0(SUF)ESP + PS"), 1.2,cDL,1.2,cCSD, -1.0,cESP, 1.0,cPS );
    }
    else if(!cSL->IsExist())
    {
        Set_LCB( nA, _T("1.2DL + 1.0EL + 1.0LL + PS"),		 1.2,cDL,1.2,cCSD,  1.0, cEL, 1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0EL + 1.0LL + PS"),		 1.2,cDL,1.2,cCSD, -1.0, cEL, 1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.0(SUF)ESP + 1.0LL + PS"), 1.2,cDL,1.2,cCSD,  1.0,cESP, 1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0(SUF)ESP + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, -1.0,cESP, 1.0,cLL,1.0,cCSL, 1.0,cPS );
    }
    else if(!bExistLL)
    {
        Set_LCB( nA, _T("1.2DL + 1.0EL + 0.2SL + PS"),		 1.2,cDL,1.2,cCSD,  1.0, cEL, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0EL + 0.2SL + PS"),		 1.2,cDL,1.2,cCSD, -1.0, cEL, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.0(SUF)ESP + 0.2SL + PS"), 1.2,cDL,1.2,cCSD,  1.0,cESP, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0(SUF)ESP + 0.2SL + PS"), 1.2,cDL,1.2,cCSD, -1.0,cESP, 0.2,cSL, 1.0,cPS );
    }
    else
    {
        Set_LCB( nA, _T("1.2DL + 1.0EL + 1.0LL + 0.2SL + PS"),		 1.2,cDL,1.2,cCSD,  1.0, cEL, 1.0,cLL,1.0,cCSL, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0EL + 1.0LL + 0.2SL + PS"),		 1.2,cDL,1.2,cCSD, -1.0, cEL, 1.0,cLL,1.0,cCSL, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.0(SUF)ESP + 1.0LL + 0.2SL + PS"), 1.2,cDL,1.2,cCSD,  1.0,cESP, 1.0,cLL,1.0,cCSL, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0(SUF)ESP + 1.0LL + 0.2SL + PS"), 1.2,cDL,1.2,cCSD, -1.0,cESP, 1.0,cLL,1.0,cCSL, 0.2,cSL, 1.0,cPS );
    }

    //0.9D + 1.6W + 1.6H
    if(!cEP->IsExist() && !cWP->IsExist())
    {
        Set_LCB( nA, _T("0.9DL + 1.6WL + PS"), 0.9,cDL,0.9,cCSD, 1.6,cWL, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.6WL + PS"), 0.9,cDL,0.9,cCSD,-1.6,cWL, 1.0,cPS );
    }
    else if(!cWL->IsExist())
    {
        Set_LCB( nA, _T("0.9DL + 1.6(EP+WP) + PS"), 0.9,cDL,0.9,cCSD, 1.6,cEP, 1.6,cWP, 1.0,cPS );
    }
    else
    {
        Set_LCB( nA, _T("0.9DL + 1.6WL + 1.6(EP+WP) + PS"),	0.9,cDL,0.9,cCSD, 1.6,cWL, 1.6,cEP, 1.6,cWP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.6WL + 1.6(EP+WP) + PS"),	0.9,cDL,0.9,cCSD,-1.6,cWL, 1.6,cEP, 1.6,cWP, 1.0,cPS );
    }

    //0.9D + 1.0E + 1.6H		
    if(!cEP->IsExist() && !cWP->IsExist())
    {
        Set_LCB( nA, _T("0.9DL + 1.0EL + PS"),	     0.9,cDL,0.9,cCSD, 1.0,cEL,  1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.0EL + PS"),	     0.9,cDL,0.9,cCSD,-1.0,cEL,  1.0,cPS );
        Set_LCB( nA, _T("0.9DL + 1.0(SUF)ESP + PS"), 0.9,cDL,0.9,cCSD, 1.0,cESP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.0(SUF)ESP + PS"), 0.9,cDL,0.9,cCSD,-1.0,cESP, 1.0,cPS );
    }
    else if(cWL->IsExist() && !cEL->IsExist() && !cESP->IsExist())
    {
        Set_LCB( nA, _T("0.9DL + 1.6(EP+WP) + PS"), 0.9,cDL, 0.9,cCSD,1.6,cEP, 1.6,cWP, 1.0,cPS	);
    }
    else
    {
        Set_LCB( nA, _T("0.9DL + 1.0EL + 1.6(EP+WP) + PS"),	      0.9,cDL,0.9,cCSD, 1.0,cEL,  1.6,cEP, 1.6,cWP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.0EL + 1.6(EP+WP) + PS"),	      0.9,cDL,0.9,cCSD,-1.0,cEL,  1.6,cEP, 1.6,cWP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL + 1.0(SUF)ESP + 1.6(EP+WP) + PS"), 0.9,cDL,0.9,cCSD, 1.0,cESP, 1.6,cEP, 1.6,cWP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.0(SUF)ESP + 1.6(EP+WP) + PS"), 0.9,cDL,0.9,cCSD,-1.0,cESP, 1.6,cEP, 1.6,cWP, 1.0,cPS );
    }
}	

//=========================
// ALUMINUM Design Codes
//=========================
void CLoadCombCtrl::MakeALUComb_AA(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL, CombBase* cSL, CombBase* cRL, 
                                   CombBase* cIP, CombBase* cTL, CombBase* cSH, CombBase* cCR, CombBase* cWP, CombBase* cEP, CombBase* cFP,
                                   CombBase* cPS, CombBase* cESP,  CombBase* cCSD, CombBase* cCSL)
{
    /// AA ADM-ASD05
    double dSF = 1.0;
    int nA = 1 + m_nConstLoad*100;
    SetCombBaseConsiderCS(m_nConstLoad, &cDL, &cCSD, &cLL, &cCSL);
    
    Set_LCB( nA, _T("DL + (LL+LR) + PS"),              1.0,cDL,1.0,cCSD,        1.0,cLL,1.0,cCSL, 1.0,cLR,                 1.0,cPS  );
    Set_LCB( nA, _T("(DL + (LL+LR) + WL) + PS"),       dSF,cDL,dSF,cCSD,        dSF,cLL,dSF,cCSL, dSF,cLR,        dSF,cWL, 1.0,cPS  );
    Set_LCB( nA, _T("(DL + (LL+LR) - WL) + PS"),       dSF,cDL,dSF,cCSD,        dSF,cLL,dSF,cCSL, dSF,cLR, (-1.0)*dSF,cWL, 1.0,cPS  );
    Set_LCB( nA, _T("(DL + WL) + PS"),                 dSF,cDL,dSF,cCSD,        dSF,cWL,1.0,cPS                           );
    Set_LCB( nA, _T("(DL - WL) + PS"),                 dSF,cDL,dSF,cCSD, (-1.0)*dSF,cWL,1.0,cPS                           );
    Set_LCB( nA, _T("(DL + (LL+LR) + EL) + PS"),       dSF,cDL,dSF,cCSD,        dSF,cLL,dSF,cCSL, dSF,cLR,        dSF,cEL, 1.0,cPS  );
    Set_LCB( nA, _T("(DL + (LL+LR) - EL) + PS"),       dSF,cDL,dSF,cCSD,        dSF,cLL,dSF,cCSL, dSF,cLR, (-1.0)*dSF,cEL, 1.0,cPS  );
    Set_LCB( nA, _T("(DL + EL) + PS"),                 dSF,cDL,dSF,cCSD,        dSF,cEL,1.0,cPS                           );
    Set_LCB( nA, _T("(DL - EL) + PS"),                 dSF,cDL,dSF,cCSD, (-1.0)*dSF,cEL,1.0,cPS                           );
    Set_LCB( nA, _T("(DL + (LL+LR) + (SUF)ESP) + PS"), dSF,cDL,dSF,cCSD,        dSF,cLL,dSF,cCSL, dSF,cLR,        dSF,cESP, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (LL+LR) - (SUF)ESP) + PS"), dSF,cDL,dSF,cCSD,        dSF,cLL,dSF,cCSL, dSF,cLR, (-1.0)*dSF,cESP, 1.0,cPS );
    Set_LCB( nA, _T("(DL + (SUF)ESP) + PS"),           dSF,cDL,dSF,cCSD,        dSF,cESP,1.0,cPS                           );
    Set_LCB( nA, _T("(DL - (SUF)ESP) + PS"),           dSF,cDL,dSF,cCSD, (-1.0)*dSF,cESP,1.0,cPS                           );
}

void CLoadCombCtrl::MakeALUComb_AA_ASD05(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL,
                                         CombBase* cSL, CombBase* cRL, CombBase* cIP, CombBase* cTL, CombBase* cSH, 
                                         CombBase* cCR, CombBase* cWP, CombBase* cEP, CombBase* cFP, CombBase* cPS,
                                         CombBase* cESP, CombBase* cCSD, CombBase* cCSL)
{
    int nA = 1 + m_nConstLoad*100;	

    BOOL bExistLL = IsExistLL(m_nConstLoad, cLL, cCSL);
    SetCombBaseConsiderCS(m_nConstLoad, &cDL, &cCSD, &cLL, &cCSL, &cCR, nullptr, &cSH, nullptr);
    
    double dPSS = 1.0;
    CString strPSorTS = _T("PS");
    BOOL    bExistWPEP = (!cEP->IsExist() && !cWP->IsExist()) ? FALSE : TRUE;
    BOOL    bExistLSR  = (!cLR->IsExist() && !cSL->IsExist()  && !cRL->IsExist()) ? FALSE : TRUE;

    Make_SubComb_EQ1_ASCE7_02_ASD(nA, dPSS, strPSorTS, cDL, cFP, cCSD, cPS);
    Make_SubComb_EQ2_ASCE7_02_ASD(nA, dPSS, strPSorTS, bExistWPEP, cDL, cLL, cWP, cEP, NULL, cFP, cTL, cCSD, cCSL, cPS);
    Make_SubComb_EQ3_ASCE7_02_ASD(nA, dPSS, strPSorTS, bExistWPEP, bExistLSR, cDL, cLR, cSL, cRL, cWP, cEP, NULL, cFP, cCSD, cPS);
    Make_SubComb_EQ4_ASCE7_02_ASD(nA, dPSS, strPSorTS, bExistWPEP, bExistLSR, cDL, cLL, cLR, cSL, cRL, cWP, cEP, NULL, cFP, cTL, cCSD, cCSL, cPS);
    Make_SubComb_EQ5_ASCE7_02_ASD(nA, dPSS, strPSorTS, bExistWPEP, cDL, cWL, cEL, cESP, cWP, cEP, NULL, cFP, cCSD, cPS);
    Make_SubComb_EQ6_ASCE7_02_ASD(nA, dPSS, strPSorTS, bExistWPEP, bExistLSR, bExistLL, cDL, cLL, cLR, cSL, cRL, cWL, cEL, cESP, cWP, cEP, NULL, cFP, cCSD, cCSL, cPS);
    Make_SubComb_EQ7_ASCE7_02_ASD(nA, dPSS, strPSorTS, bExistWPEP, cDL, cWL, cWP, cEP, NULL, cCSD, cPS);
    Make_SubComb_EQ8_ASCE7_02_ASD(nA, dPSS, strPSorTS, bExistWPEP, cDL, cEL, cESP, cWP, cEP, NULL, cCSD, cPS);	
}


void CLoadCombCtrl::MakeALUComb_AA_LRFD05(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL, 
                                          CombBase* cSL, CombBase* cRL, CombBase* cIP, CombBase* cTL, CombBase* cSH, 
                                          CombBase* cCR, CombBase* cWP, CombBase* cEP, CombBase* cFP, CombBase* cPS, 
                                          CombBase* cESP, CombBase* cCSD, CombBase* cCSL)
{
    int nA = 1 + m_nConstLoad*100;
    BOOL bExistLL = IsExistLL(m_nConstLoad, cLL, cCSL);
    SetCombBaseConsiderCS(m_nConstLoad, &cDL, &cCSD, &cLL, &cCSL);
    
    // [ASCE7-02, 2.3.2.1] 1.4(D+F).
    if (cFP->IsExist())
    {
        Set_LCB( nA, _T("1.4(DL+FP) + PS"), 1.4,cDL,1.4,cCSD, 1.4,cFP, 1.0,cPS );    
    }
    else
    {
        Set_LCB( nA, _T("1.4DL + PS"), 1.4,cDL,1.4,cCSD, 1.0,cPS );
    }


    // [ASCE7-02, 2.3.2.2] 1.2(D+F+T) + 1.6(L+H) + 0.5(LR or S or R) .
    if ( !cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist() )
    {
        Set_LCB( nA, _T("1.2(DL+FP+TL) + 1.6(LL+(EP+WP)) + PS"), 1.2,cDL,1.2,cCSD, 1.2,cFP, 1.2,cTL,	1.6,cLL,1.6,cCSL, 1.6,cEP, 1.6,cWP, 1.0,cPS);
    }
    else 
    {
        Set_LCB( nA, _T("1.2(DL+FP+TL) + 1.6(LL+(EP+WP)) + 0.5LR + PS"), 1.2,cDL,1.2,cCSD,1.2,cFP, 1.2,cTL,	1.6,cLL,1.6,cCSL, 1.6,cEP,1.6,cWP,	0.5,cLR,1.0,cPS );
        Set_LCB( nA, _T("1.2(DL+FP+TL) + 1.6(LL+(EP+WP)) + 0.5SL + PS"), 1.2,cDL,1.2,cCSD,1.2,cFP, 1.2,cTL,	1.6,cLL,1.6,cCSL, 1.6,cEP,1.6,cWP,	0.5,cSL,1.0,cPS );
        Set_LCB( nA, _T("1.2(DL+FP+TL) + 1.6(LL+(EP+WP)) + 0.5RL + PS"), 1.2,cDL,1.2,cCSD,1.2,cFP, 1.2,cTL,	1.6,cLL,1.6,cCSL, 1.6,cEP,1.6,cWP,	0.5,cRL,1.0,cPS );
    }

    // [ASCE7-02, 2.3.2.3] 1.2D + 1.6(LR or S or R) + (0.5L or 0.8W).
    // PMS:4168-Seungjun-20100405 1.2D + 1.6(LR or S or R) + (1.0L or 0.8W).
    if ( !bExistLL && !cWL->IsExist() )
    {
        Set_LCB( nA, _T("1.2DL + 1.6LR + PS"), 1.2,cDL,1.2,cCSD, 1.6,cLR, 1.0,cPS);
        Set_LCB( nA, _T("1.2DL + 1.6SL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cSL, 1.0,cPS);
        Set_LCB( nA, _T("1.2DL + 1.6RL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cRL, 1.0,cPS);
    }
    else
    {
        Set_LCB( nA, _T("1.2DL + 1.6LR + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cLR,  1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6LR + 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cLR,  0.8,cWL,	1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6LR - 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cLR, -0.8,cWL,	1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6SL + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cSL,  1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6SL + 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cSL,  0.8,cWL,	1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6SL - 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cSL, -0.8,cWL,	1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6RL + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cRL,  1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6RL + 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cRL,  0.8,cWL,	1.0,cPS	);
        Set_LCB( nA, _T("1.2DL + 1.6RL - 0.8WL + PS"), 1.2,cDL,1.2,cCSD, 1.6,cRL, -0.8,cWL,	1.0,cPS	);
    }

    // [ASCE7-02, 2.3.2.4] 1.2D + 1.6W + 0.5L + 0.5(LR or S or R).
    // PMS:4168-Seungjun-20100405 1.2D + 1.6W + 1.0L + 0.5(LR or S or R).
    if(!bExistLL && !cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist())
    {
        Set_LCB( nA, _T("1.2DL + 1.6WL + PS"), 1.2,cDL,1.2,cCSD,  1.6,cWL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + PS"), 1.2,cDL,1.2,cCSD, -1.6,cWL, 1.0,cPS );
    }
    else if(!cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist())
    {
        Set_LCB( nA, _T("1.2DL + 1.6WL + 1.0LL + PS"), 1.2,cDL,1.2,cCSD,  1.6,cWL, 1.0,cLL,1.0,cCSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, -1.6,cWL, 1.0,cLL,1.0,cCSL, 1.0,cPS );
    }
    else if(!bExistLL)
    {
        Set_LCB( nA, _T("1.2DL + 1.6WL + 0.5LR + PS"), 1.2,cDL,1.2,cCSD,  1.6,cWL, 0.5,cLR, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 0.5LR + PS"), 1.2,cDL,1.2,cCSD, -1.6,cWL, 0.5,cLR, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6WL + 0.5SL + PS"), 1.2,cDL,1.2,cCSD,  1.6,cWL, 0.5,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 0.5SL + PS"), 1.2,cDL,1.2,cCSD, -1.6,cWL, 0.5,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.6WL + 0.5RL + PS"), 1.2,cDL,1.2,cCSD,  1.6,cWL, 0.5,cRL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.6WL + 0.5RL + PS"), 1.2,cDL,1.2,cCSD, -1.6,cWL, 0.5,cRL, 1.0,cPS );
    }
    else
    {
        Set_LCB( nA, _T("1.2DL + 1.6WL + 1.0LL + 0.5LR + PS"), 1.2,cDL,1.2,cCSD,  1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cLR, 1.0,cPS);
        Set_LCB( nA, _T("1.2DL - 1.6WL + 1.0LL + 0.5LR + PS"), 1.2,cDL,1.2,cCSD, -1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cLR, 1.0,cPS);
        Set_LCB( nA, _T("1.2DL + 1.6WL + 1.0LL + 0.5SL + PS"), 1.2,cDL,1.2,cCSD,  1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cSL, 1.0,cPS);
        Set_LCB( nA, _T("1.2DL - 1.6WL + 1.0LL + 0.5SL + PS"), 1.2,cDL,1.2,cCSD, -1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cSL, 1.0,cPS);
        Set_LCB( nA, _T("1.2DL + 1.6WL + 1.0LL + 0.5RL + PS"), 1.2,cDL,1.2,cCSD,  1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cRL, 1.0,cPS);
        Set_LCB( nA, _T("1.2DL - 1.6WL + 1.0LL + 0.5RL + PS"), 1.2,cDL,1.2,cCSD, -1.6,cWL, 1.0,cLL,1.0,cCSL, 0.5,cRL, 1.0,cPS);
    }

    // [ASCE7-02, 2.3.2.5] 1.2D +(-) 1.0E + 0.5L + 0.2S.
    // PMS:4168-Seungjun-20100405 1.2D +(-) 1.0E + 1.0L + 0.2S.
    if(!bExistLL && !cSL->IsExist())
    {
        Set_LCB( nA, _T("1.2DL + 1.0EL + PS"), 1.2,cDL,1.2,cCSD,  1.0,cEL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0EL + PS"), 1.2,cDL,1.2,cCSD, -1.0,cEL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.0(SUF)ESP + PS"), 1.2,cDL,1.2,cCSD,  1.0,cESP, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0(SUF)ESP + PS"), 1.2,cDL,1.2,cCSD, -1.0,cESP, 1.0,cPS );
    }
    else if(!cSL->IsExist())
    {
        Set_LCB( nA, _T("1.2DL + 1.0EL + 1.0LL + PS"),	     1.2,cDL,1.2,cCSD,  1.0,cEL,  1.0,cLL,1.0,cCSL, 1.0,cPS	);
        Set_LCB( nA, _T("1.2DL - 1.0EL + 1.0LL + PS"),	     1.2,cDL,1.2,cCSD, -1.0,cEL,  1.0,cLL,1.0,cCSL, 1.0,cPS	);
        Set_LCB( nA, _T("1.2DL + 1.0(SUF)ESP + 1.0LL + PS"), 1.2,cDL,1.2,cCSD,	1.0,cESP, 1.0,cLL,1.0,cCSL, 1.0,cPS	);
        Set_LCB( nA, _T("1.2DL - 1.0(SUF)ESP + 1.0LL + PS"), 1.2,cDL,1.2,cCSD, -1.0,cESP, 1.0,cLL,1.0,cCSL, 1.0,cPS	);
    }
    else if(!bExistLL)
    {
        Set_LCB( nA, _T("1.2DL + 1.0EL + 0.2SL + PS"),	      1.2,cDL,1.2,cCSD,	 1.0,cEL,  0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0EL + 0.2SL + PS"),	      1.2,cDL,1.2,cCSD, -1.0,cEL,  0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.0(SUF)ESP + 0.2SL + PS"),  1.2,cDL,1.2,cCSD,	 1.0,cESP, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0(SUF)ESP + 0.2SL + PS"),  1.2,cDL,1.2,cCSD, -1.0,cESP, 0.2,cSL, 1.0,cPS );
    }
    else
    {
        Set_LCB( nA, _T("1.2DL + 1.0EL + 1.0LL + 0.2SL + PS"),       1.2,cDL,1.2,cCSD,	1.0,cEL,  1.0,cLL,1.0,cCSL, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0EL + 1.0LL + 0.2SL + PS"),       1.2,cDL,1.2,cCSD, -1.0,cEL,  1.0,cLL,1.0,cCSL, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL + 1.0(SUF)ESP + 1.0LL + 0.2SL + PS"), 1.2,cDL,1.2,cCSD,	1.0,cESP, 1.0,cLL,1.0,cCSL, 0.2,cSL, 1.0,cPS );
        Set_LCB( nA, _T("1.2DL - 1.0(SUF)ESP + 1.0LL + 0.2SL + PS"), 1.2,cDL,1.2,cCSD, -1.0,cESP, 1.0,cLL,1.0,cCSL, 0.2,cSL, 1.0,cPS );
    }

    // [ASCE7-02, 2.3.2.6] 0.9D +(-) 1.6W + 1.6H.
    if(!cEP->IsExist() && !cWP->IsExist())
    {
        Set_LCB( nA, _T("0.9DL + 1.6WL + PS"), 0.9,cDL,0.9,cCSD, 1.6,cWL, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.6WL + PS"), 0.9,cDL,0.9,cCSD,-1.6,cWL, 1.0,cPS );
    }
    else if(!cWL->IsExist())
    {
        Set_LCB( nA, _T("0.9DL + 1.6(EP+WP) + PS"), 0.9,cDL,0.9,cCSD, 1.6,cEP, 1.6,cWP, 1.0,cPS	);
    }
    else
    {
        Set_LCB( nA, _T("0.9DL + 1.6WL + 1.6(EP+WP) + PS"),	0.9,cDL,0.9,cCSD, 1.6,cWL, 1.6,cEP, 1.6,cWP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.6WL + 1.6(EP+WP) + PS"),	0.9,cDL,0.9,cCSD,-1.6,cWL, 1.6,cEP, 1.6,cWP, 1.0,cPS );
    }

    // [ASCE7-02, 2.3.2.7] 0.9D + 1.0E + 1.6H.
    if(!cEP->IsExist())
    {
        Set_LCB( nA, _T("0.9DL + 1.0EL + PS"),		 0.9,cDL,0.9,cCSD,  1.0,cEL,  1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.0EL + PS"),		 0.9,cDL,0.9,cCSD, -1.0,cEL,  1.0,cPS );
        Set_LCB( nA, _T("0.9DL + 1.0(SUF)ESP + PS"), 0.9,cDL,0.9,cCSD,  1.0,cESP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.0(SUF)ESP + PS"), 0.9,cDL,0.9,cCSD, -1.0,cESP, 1.0,cPS );
    }
    else if(!cEL->IsExist() && !cESP->IsExist())
    {
        Set_LCB( nA, _T("0.9DL + 1.6(EP+WP) + PS"), 0.9,cDL,0.9,cCSD, 1.6,cEP, 1.6,cWP, 1.0,cPS );
    }
    else
    {
        Set_LCB( nA, _T("0.9DL + 1.0EL + 1.6(EP+WP) + PS"),		  0.9,cDL,0.9,cCSD,  1.0,cEL,  1.6,cEP, 1.6,cWP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.0EL + 1.6(EP+WP) + PS"),		  0.9,cDL,0.9,cCSD, -1.0,cEL,  1.6,cEP, 1.6,cWP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL + 1.0(SUF)ESP + 1.6(EP+WP) + PS"), 0.9,cDL,0.9,cCSD,  1.0,cESP, 1.6,cEP, 1.6,cWP, 1.0,cPS );
        Set_LCB( nA, _T("0.9DL - 1.0(SUF)ESP + 1.6(EP+WP) + PS"), 0.9,cDL,0.9,cCSD, -1.0,cESP, 1.6,cEP, 1.6,cWP, 1.0,cPS );
    }
}


void CLoadCombCtrl::MakeComb_KBC2016(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL, CombBase* cSL, CombBase* cRL, CombBase* cIP,
                                     CombBase* cTL, CombBase* cSH, CombBase* cCR, CombBase* cFP, CombBase* cPS, CombBase* cESP, CombBase* cTP, CombBase* cTS,
                                     CombBase* cSUM, CombBase* cCSD, CombBase* cCSL, CombBase* cCSC, CombBase* cCSS, CombBase* cIL, CombBase* cEPV)
{
    // If construction stage analysis, PS is replaced with TP,TS,SUM.
    // Transfer Stage     -> m_dLossFactorTransfer.
    // Service Load Stage -> m_dLossFactorService.
    double dPST = (m_bLossFactor ? m_dLossFactorTransfer : 1.0);
    double dPSS = (m_bLossFactor ? m_dLossFactorService  : 1.0);
    double dSF  = 1.0;	// Safety Factor.
    int iLcomType = Get_CurrentLoadCombType();
    BOOL bIsFDN = ( (iLcomType==D_LCOMTYPE_FDN || m_nDesignType==3) ? TRUE:FALSE);
    
    int nA = 1 + m_nConstLoad*100;
    BOOL bExistLL = IsExistLL(m_nConstLoad, cLL, cCSL);
    SetCombBaseConsiderCS(m_nConstLoad, &cDL, &cCSD, &cLL, &cCSL, &cCR, &cCSC, &cSH, &cCSS);
    
    SetAddSeisLcomParam();

    BOOL bStageCS = IsStageCS();

    if(m_nLcomType==D_LCOMTYPE_GENERAL)	Make_LCB_OnlyRespEccn(nA, cESP);

    CString   strPsTs = bStageCS ? _T("TS") : _T("PS");
    CombBase* cPsTs   = bStageCS?     cTS   :    cPS;

    m_iSetLcomForKBC = 0;
    Set_PrevLcomSRSS(FALSE,1.0,1.0, cEL,cESP);

    MakeWindLoadGroupMapKBC2016(m_mWindGroup);
    Set_WindDirCombKBC2016();

    int nActiveSTRN = nA;
    Make_SubComb_EQ01_KBC2016(nActiveSTRN, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ02_KBC2016(nActiveSTRN, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ03_KBC2016(nActiveSTRN, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ04_KBC2016(nActiveSTRN, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ05_KBC2016(nActiveSTRN, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ06_KBC2016(nActiveSTRN, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ07_KBC2016(nActiveSTRN, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);  

    int nActiveSERV = nA + 1;
    Make_SubComb_EQ08_KBC2016(nActiveSERV, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ09_KBC2016(nActiveSERV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cTL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ10_KBC2016(nActiveSERV, bExistLL, cDL, cCSD, cEPV, cFP, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ11_KBC2016(nActiveSERV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cTL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ12_KBC2016(nActiveSERV, FALSE, cDL, cCSD, cEPV, cFP, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ13_KBC2016(nActiveSERV, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ14_KBC2016(nActiveSERV, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ15_KBC2016(nActiveSERV, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

    if(bStageCS) // For Construction Stage Analysis, consider Transfer Stage.
    {
        if(fabs(dPST-1.0) < m_dZeroLim)	Set_LCB(nActiveSERV, _T("(SUM-TP-TS) + (1.0)TS") ,  1.0,cSUM, (-1.0),cTP);
        else							Set_LCB(nActiveSERV, _T("(SUM-TP-TS) + (SFAT)TS"),	 1.0,cSUM, (-1.0),cTP, dPST-1.0,cTS );
    }

    //++++++++++++++++++++++++++++++++++++++++
    // Special
    //++++++++++++++++++++++++++++++++++++++++
    if (m_bSlcmSpecial)
    {
        m_iSetLcomForKBC = 1;
        Set_PrevLcomSRSS(TRUE,1.0,1.0, cEL,cESP);

        int nActiveSPEC = nA + 3;
        Make_SubComb_EQ01_KBC2016(nActiveSPEC, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KBC2016(nActiveSPEC, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KBC2016(nActiveSPEC, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KBC2016(nActiveSPEC, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KBC2016(nActiveSPEC, bExistLL, TRUE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KBC2016(nActiveSPEC, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KBC2016(nActiveSPEC, TRUE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);  

        if(bStageCS) // For Construction Stage Analysis, consider Transfer Stage.
        {
            if(fabs(dPST-1.0) < m_dZeroLim)	Set_LCB(nA+2, _T("(SUM-TP-TS) + (1.0)TS") ,  1.0,cSUM, (-1.0),cTP);
            else							Set_LCB(nA+2, _T("(SUM-TP-TS) + (SFAT)TS"),	 1.0,cSUM, (-1.0),cTP, dPST-1.0,cTS );
        }
    }

    if (m_bSlcmVertical)
    {
        m_iSetLcomForKBC = 2;
        Set_PrevLcomSRSS(FALSE,1.,1., cEL,cESP);
        double dDLv = dSF*(-1)*m_dSlcmVertical;

        int nActiveVERT = nA + 4;
        Make_SubComb_EQ01_KBC2016(nActiveVERT, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KBC2016(nActiveVERT, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KBC2016(nActiveVERT, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KBC2016(nActiveVERT, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KBC2016(nActiveVERT, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KBC2016(nActiveVERT, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KBC2016(nActiveVERT, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

        if (bStageCS)	// For Construction Stage Analysis.
        {
            Set_LCB(nActiveVERT, _T("-(VER)DL + 1.0EL + (SFAC)TS"),  	  dDLv,cDL,dDLv,cCSD, 1.0,cEL, dPSS,cTS);
            Set_LCB(nActiveVERT, _T("-(VER)DL - 1.0EL + (SFAC)TS"),		  dDLv,cDL,dDLv,cCSD,-1.0,cEL, dPSS,cTS);
            Set_LCB(nActiveVERT, _T("-(VER)DL + 1.0(SUF)ESP + (SFAC)TS"), dDLv,cDL,dDLv,cCSD, 1.0,cESP,dPSS,cTS);
            Set_LCB(nActiveVERT, _T("-(VER)DL - 1.0(SUF)ESP + (SFAC)TS"), dDLv,cDL,dDLv,cCSD,-1.0,cESP,dPSS,cTS);

            // Transfer Stage.
            if(fabs(dPST-1.0) < m_dZeroLim)	Set_LCB(nA+2, _T("(SUM-TP-TS) + (1.0)TS") ,  1.0,cSUM, (-1.0),cTP);
            else							Set_LCB(nA+2, _T("(SUM-TP-TS) + (SFAT)TS"),	 1.0,cSUM, (-1.0),cTP, dPST-1.0,cTS );
        }
        else// For NON-Construction Stage Analysis.
        {
            Set_LCB(nActiveVERT, _T("-(VER)DL + 1.0EL + (SFAC)PS"),		  dDLv,cDL,dDLv,cCSD, 1.0,cEL, dPSS,cPS);
            Set_LCB(nActiveVERT, _T("-(VER)DL - 1.0EL + (SFAC)PS"),		  dDLv,cDL,dDLv,cCSD,-1.0,cEL, dPSS,cPS);
            Set_LCB(nActiveVERT, _T("-(VER)DL + 1.0(SUF)ESP + (SFAC)PS"), dDLv,cDL,dDLv,cCSD, 1.0,cESP,dPSS,cPS);
            Set_LCB(nActiveVERT, _T("-(VER)DL - 1.0(SUF)ESP + (SFAC)PS"), dDLv,cDL,dDLv,cCSD,-1.0,cESP,dPSS,cPS);
        }
    }

    // Add by ZINU.('05.04.19). Consider SRSS.
    if(m_nOrthoType==1)	m_iSetLcomForSRSS = 0; 
}

void CLoadCombCtrl::MakeComb_KDS41_2018(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL,
                                        CombBase* cSL, CombBase* cRL, CombBase* cIP, CombBase* cTL, CombBase* cSH,
                                        CombBase* cCR, CombBase* cFP, CombBase* cPS, CombBase* cESP, CombBase* cTP, 
                                        CombBase* cTS, CombBase* cSUM, CombBase* cCSD, CombBase* cCSL, CombBase* cCSC, 
                                        CombBase* cCSS, CombBase* cIL, CombBase* cEPV)
{
    const double dPST = GetPSLossFactorTransfer();
    const double dPSS = GetPSLossFactorService(); 
    
    const int iLcomType = Get_CurrentLoadCombType();
    BOOL bIsFDN = ((iLcomType==D_LCOMTYPE_FDN || m_nDesignType==3) ? TRUE:FALSE);

    const int nA = 1 + m_nConstLoad*100;
    BOOL bExistLL = IsExistLL(m_nConstLoad, cLL, cCSL);
    SetCombBaseConsiderCS(m_nConstLoad, &cDL, &cCSD, &cLL, &cCSL, &cCR, &cCSC, &cSH, &cCSS);

    SetAddSeisLcomParam();

    BOOL bStageCS = IsStageCS();

    if ( m_nLcomType==D_LCOMTYPE_GENERAL )
    {
        Make_LCB_OnlyRespEccn(nA, cESP);
    }

    CString   strPsTs = bStageCS ? _T("TS") : _T("PS");
    CombBase* cPsTs   = bStageCS?     cTS   :    cPS;

    m_iSetLcomForKBC = 0;
    Set_PrevLcomSRSS(FALSE, 1.0, 1.0, cEL, cESP);

    MakeWindLoadGroupMapKBC2016(m_mWindGroup);
    Set_WindDirCombKBC2016();

    const int nA_STRN = nA;
    Make_SubComb_EQ01_KBC2016(nA_STRN, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ02_KBC2016(nA_STRN, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ03_KBC2016(nA_STRN, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ04_KBC2016(nA_STRN, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ05_KBC2016(nA_STRN, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ06_KBC2016(nA_STRN, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ07_KBC2016(nA_STRN, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

    const int nA_SERV = nA + 1;
    Make_SubComb_EQ08_KBC2016(nA_SERV, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ09_KBC2016(nA_SERV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cTL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ10_KBC2016(nA_SERV, bExistLL, cDL, cCSD, cEPV, cFP, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ11_KBC2016(nA_SERV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cTL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ12_KBC2016(nA_SERV, FALSE, cDL, cCSD, cEPV, cFP, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ13_KBC2016(nA_SERV, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ14_KBC2016(nA_SERV, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ15_KBC2016(nA_SERV, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

    if ( bStageCS ) // For Construction Stage Analysis, consider Transfer Stage.
    {
        if ( fabs(dPST-1.0) < m_dZeroLim )
        {
            Set_LCB(nA_SERV, _T("(SUM-TP-TS) + (1.0)TS"), 1.0, cSUM, (-1.0), cTP);
        }
        else
        {
            Set_LCB(nA_SERV, _T("(SUM-TP-TS) + (SFAT)TS"), 1.0, cSUM, (-1.0), cTP, dPST-1.0, cTS);
        }
    }

    const int nA_SPEC = nA + 3;
    if ( m_bSlcmSpecial )
    {
        m_iSetLcomForKBC = 1;
        Set_PrevLcomSRSS(TRUE, 1.0, 1.0, cEL, cESP);
                
        Make_SubComb_EQ01_KBC2016(nA_SPEC, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KBC2016(nA_SPEC, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KBC2016(nA_SPEC, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KBC2016(nA_SPEC, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KBC2016(nA_SPEC, bExistLL, TRUE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KBC2016(nA_SPEC, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KBC2016(nA_SPEC, TRUE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

        if ( bStageCS ) // For Construction Stage Analysis, consider Transfer Stage.
        {
            if ( fabs(dPST-1.0) < m_dZeroLim )	Set_LCB(nA+2, _T("(SUM-TP-TS) + (1.0)TS"), 1.0, cSUM, (-1.0), cTP);
            else								Set_LCB(nA+2, _T("(SUM-TP-TS) + (SFAT)TS"), 1.0, cSUM, (-1.0), cTP, dPST-1.0, cTS);
        }
    }

    if ( m_bSlcmVertical )
    {
        m_iSetLcomForKBC = 2;
        Set_PrevLcomSRSS(FALSE, 1., 1., cEL, cESP);
        double dDLv = (-1.0)*m_dSlcmVertical;

        const int nA_VERT = nA + 4;
        Make_SubComb_EQ01_KBC2016(nA_VERT, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KBC2016(nA_VERT, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KBC2016(nA_VERT, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KBC2016(nA_VERT, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KBC2016(nA_VERT, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KBC2016(nA_VERT, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KBC2016(nA_VERT, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

        if ( bStageCS )	// For Construction Stage Analysis.
        {
            Set_LCB(nA_VERT, _T("-(VER)DL + 1.0EL + (SFAC)TS"), dDLv, cDL, dDLv, cCSD, 1.0, cEL, dPSS, cTS);
            Set_LCB(nA_VERT, _T("-(VER)DL - 1.0EL + (SFAC)TS"), dDLv, cDL, dDLv, cCSD, -1.0, cEL, dPSS, cTS);
            Set_LCB(nA_VERT, _T("-(VER)DL + 1.0(SUF)ESP + (SFAC)TS"), dDLv, cDL, dDLv, cCSD, 1.0, cESP, dPSS, cTS);
            Set_LCB(nA_VERT, _T("-(VER)DL - 1.0(SUF)ESP + (SFAC)TS"), dDLv, cDL, dDLv, cCSD, -1.0, cESP, dPSS, cTS);

            // Transfer Stage.
            if ( fabs(dPST-1.0) < m_dZeroLim )
            {
                Set_LCB(nA+2, _T("(SUM-TP-TS) + (1.0)TS"), 1.0, cSUM, (-1.0), cTP);
            }
            else
            {
                Set_LCB(nA+2, _T("(SUM-TP-TS) + (SFAT)TS"), 1.0, cSUM, (-1.0), cTP, dPST-1.0, cTS);
            }
        }
        else// For NON-Construction Stage Analysis.
        {
            Set_LCB(nA_VERT, _T("-(VER)DL + 1.0EL + (SFAC)PS"), dDLv, cDL, dDLv, cCSD, 1.0, cEL, dPSS, cPS);
            Set_LCB(nA_VERT, _T("-(VER)DL - 1.0EL + (SFAC)PS"), dDLv, cDL, dDLv, cCSD, -1.0, cEL, dPSS, cPS);
            Set_LCB(nA_VERT, _T("-(VER)DL + 1.0(SUF)ESP + (SFAC)PS"), dDLv, cDL, dDLv, cCSD, 1.0, cESP, dPSS, cPS);
            Set_LCB(nA_VERT, _T("-(VER)DL - 1.0(SUF)ESP + (SFAC)PS"), dDLv, cDL, dDLv, cCSD, -1.0, cESP, dPSS, cPS);
        }
    }

    m_bModeUG = TRUE;
        
    SetAddSeisLcomParamUG();
    
    if ( m_bLcomUG )
    {
        m_iSetLcomForKBC = 0;
        Set_PrevLcomSRSS(FALSE, 1.0, 1.0, cEL, cESP);
        Set_PrevLcomSRSS_UGEP(FALSE);

        const int nA_UGST = nA_STRN;
        Make_SubComb_EQ01_KBC2016(nA_UGST, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KBC2016(nA_UGST, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KBC2016(nA_UGST, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KBC2016(nA_UGST, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KBC2016(nA_UGST, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KBC2016(nA_UGST, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KBC2016(nA_UGST, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);
        
        const int nA_UGSV = nA_SERV;
        Make_SubComb_EQ08_KBC2016(nA_UGSV, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ09_KBC2016(nA_UGSV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cTL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ10_KBC2016(nA_UGSV, bExistLL, cDL, cCSD, cEPV, cFP, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ11_KBC2016(nA_UGSV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cTL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ12_KBC2016(nA_UGSV, FALSE, cDL, cCSD, cEPV, cFP, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ13_KBC2016(nA_UGSV, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ14_KBC2016(nA_UGSV, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ15_KBC2016(nA_UGSV, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);        
    }

    if ( m_bLcomUGSpec )
    {
        m_iSetLcomForKBC = 1;
        Set_PrevLcomSRSS(TRUE, 1.0, 1.0, cEL, cESP);
        Set_PrevLcomSRSS_UGEP(TRUE);

        const int nA_UGSP = nA_SPEC;
        Make_SubComb_EQ01_KBC2016(nA_UGSP, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KBC2016(nA_UGSP, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KBC2016(nA_UGSP, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KBC2016(nA_UGSP, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KBC2016(nA_UGSP, bExistLL, TRUE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KBC2016(nA_UGSP, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KBC2016(nA_UGSP, TRUE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);
    }

    // Add by ZINU.('05.04.19). Consider SRSS.
    if ( m_nOrthoType==1 )	m_iSetLcomForSRSS = 0;

    m_bModeUG = FALSE;
}

void CLoadCombCtrl::MakeComb_KDS41_2021(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cWL, CombBase* cEL,
    CombBase* cSL, CombBase* cRL, CombBase* cIP, CombBase* cTL, CombBase* cSH,
    CombBase* cCR, CombBase* cFP, CombBase* cPS, CombBase* cESP, CombBase* cTP,
    CombBase* cTS, CombBase* cSUM, CombBase* cCSD, CombBase* cCSL, CombBase* cCSC,
    CombBase* cCSS, CombBase* cIL, CombBase* cEPV)
{
    const double dPST = GetPSLossFactorTransfer();
    const double dPSS = GetPSLossFactorService();

    const int iLcomType = Get_CurrentLoadCombType();
    BOOL bIsFDN = ((iLcomType==D_LCOMTYPE_FDN || m_nDesignType==3) ? TRUE:FALSE);

    const int nA = 1 + m_nConstLoad*100;
    BOOL bExistLL = IsExistLL(m_nConstLoad, cLL, cCSL);
    SetCombBaseConsiderCS(m_nConstLoad, &cDL, &cCSD, &cLL, &cCSL, &cCR, &cCSC, &cSH, &cCSS);

    SetAddSeisLcomParam();
    if ( m_nLcomType==D_LCOMTYPE_GENERAL )
    {
        Make_LCB_OnlyRespEccn(nA, cESP);
    }

    BOOL bStageCS = IsStageCS();
    const CString& strPsTs = bStageCS ? _T("TS") : _T("PS");
    CombBase* cPsTs = bStageCS ? cTS : cPS;

    m_iSetLcomForKBC = 0;
    Set_PrevLcomSRSS(FALSE, 1.0, 1.0, cEL, cESP);

    MakeWindLoadGroupMapKBC2016(m_mWindGroup);
    Set_WindDirCombKBC2016();

    const int nA_STRN = nA;
    Make_SubComb_EQ01_KDS41_10_15_2021(nA_STRN, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ02_KDS41_10_15_2021(nA_STRN, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ03_KDS41_10_15_2021(nA_STRN, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ04_KDS41_10_15_2021(nA_STRN, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ05_KDS41_10_15_2021(nA_STRN, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ06_KDS41_10_15_2021(nA_STRN, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ07_KDS41_10_15_2021(nA_STRN, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

    const int nA_SERV = nA + 1;
    Make_SubComb_EQ08_KDS41_10_15_2021(nA_SERV, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ09_KDS41_10_15_2021(nA_SERV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cTL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ10_KDS41_10_15_2021(nA_SERV, bExistLL, cDL, cCSD, cEPV, cFP, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ11_KDS41_10_15_2021(nA_SERV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cTL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ12_KDS41_10_15_2021(nA_SERV, FALSE, cDL, cCSD, cEPV, cFP, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ13_KDS41_10_15_2021(nA_SERV, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ14_KDS41_10_15_2021(nA_SERV, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
    Make_SubComb_EQ15_KDS41_10_15_2021(nA_SERV, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

    if ( bStageCS ) // For Construction Stage Analysis, consider Transfer Stage.
    {
        if ( fabs(dPST-1.0) < m_dZeroLim )
        {
            Set_LCB(nA_SERV, _T("(SUM-TP-TS) + (1.0)TS"), 1.0, cSUM, (-1.0), cTP);
        }
        else
        {
            Set_LCB(nA_SERV, _T("(SUM-TP-TS) + (SFAT)TS"), 1.0, cSUM, (-1.0), cTP, dPST-1.0, cTS);
        }
    }

    const int nA_SPEC = nA + 3;
    if ( m_bSlcmSpecial )
    {
        m_iSetLcomForKBC = 1;
        Set_PrevLcomSRSS(TRUE, 1.0, 1.0, cEL, cESP);

        Make_SubComb_EQ01_KDS41_10_15_2021(nA_SPEC, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KDS41_10_15_2021(nA_SPEC, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KDS41_10_15_2021(nA_SPEC, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KDS41_10_15_2021(nA_SPEC, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KDS41_10_15_2021(nA_SPEC, bExistLL, TRUE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KDS41_10_15_2021(nA_SPEC, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KDS41_10_15_2021(nA_SPEC, TRUE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

        if ( bStageCS ) // For Construction Stage Analysis, consider Transfer Stage.
        {
            if ( fabs(dPST-1.0) < m_dZeroLim )	Set_LCB(nA+2, _T("(SUM-TP-TS) + (1.0)TS"), 1.0, cSUM, (-1.0), cTP);
            else								Set_LCB(nA+2, _T("(SUM-TP-TS) + (SFAT)TS"), 1.0, cSUM, (-1.0), cTP, dPST-1.0, cTS);
        }
    }

    if ( m_bSlcmVertical )
    {
        m_iSetLcomForKBC = 2;
        Set_PrevLcomSRSS(FALSE, 1., 1., cEL, cESP);
        double dDLv = (-1.0)*m_dSlcmVertical;

        const int nA_VERT = nA + 4;
        Make_SubComb_EQ01_KDS41_10_15_2021(nA_VERT, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KDS41_10_15_2021(nA_VERT, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KDS41_10_15_2021(nA_VERT, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KDS41_10_15_2021(nA_VERT, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KDS41_10_15_2021(nA_VERT, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KDS41_10_15_2021(nA_VERT, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KDS41_10_15_2021(nA_VERT, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

        if ( bStageCS )	// For Construction Stage Analysis.
        {
            Set_LCB(nA_VERT, _T("-(VER)DL + 1.0EL + (SFAC)TS"), dDLv, cDL, dDLv, cCSD, 1.0, cEL, dPSS, cTS);
            Set_LCB(nA_VERT, _T("-(VER)DL - 1.0EL + (SFAC)TS"), dDLv, cDL, dDLv, cCSD, -1.0, cEL, dPSS, cTS);
            Set_LCB(nA_VERT, _T("-(VER)DL + 1.0(SUF)ESP + (SFAC)TS"), dDLv, cDL, dDLv, cCSD, 1.0, cESP, dPSS, cTS);
            Set_LCB(nA_VERT, _T("-(VER)DL - 1.0(SUF)ESP + (SFAC)TS"), dDLv, cDL, dDLv, cCSD, -1.0, cESP, dPSS, cTS);

            // Transfer Stage.
            if ( fabs(dPST-1.0) < m_dZeroLim )
            {
                Set_LCB(nA+2, _T("(SUM-TP-TS) + (1.0)TS"), 1.0, cSUM, (-1.0), cTP);
            }
            else
            {
                Set_LCB(nA+2, _T("(SUM-TP-TS) + (SFAT)TS"), 1.0, cSUM, (-1.0), cTP, dPST-1.0, cTS);
            }
        }
        else// For NON-Construction Stage Analysis.
        {
            Set_LCB(nA_VERT, _T("-(VER)DL + 1.0EL + (SFAC)PS"), dDLv, cDL, dDLv, cCSD, 1.0, cEL, dPSS, cPS);
            Set_LCB(nA_VERT, _T("-(VER)DL - 1.0EL + (SFAC)PS"), dDLv, cDL, dDLv, cCSD, -1.0, cEL, dPSS, cPS);
            Set_LCB(nA_VERT, _T("-(VER)DL + 1.0(SUF)ESP + (SFAC)PS"), dDLv, cDL, dDLv, cCSD, 1.0, cESP, dPSS, cPS);
            Set_LCB(nA_VERT, _T("-(VER)DL - 1.0(SUF)ESP + (SFAC)PS"), dDLv, cDL, dDLv, cCSD, -1.0, cESP, dPSS, cPS);
        }
    }

    m_bModeUG = TRUE;

    SetAddSeisLcomParamUG();

    if ( m_bLcomUG )
    {
        m_iSetLcomForKBC = 0;
        Set_PrevLcomSRSS(FALSE, 1.0, 1.0, cEL, cESP);
        Set_PrevLcomSRSS_UGEP(FALSE);

        const int nA_UGST = nA_STRN;
        Make_SubComb_EQ01_KDS41_10_15_2021(nA_UGST, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KDS41_10_15_2021(nA_UGST, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KDS41_10_15_2021(nA_UGST, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KDS41_10_15_2021(nA_UGST, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KDS41_10_15_2021(nA_UGST, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KDS41_10_15_2021(nA_UGST, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KDS41_10_15_2021(nA_UGST, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);

        const int nA_UGSV = nA_SERV;
        Make_SubComb_EQ08_KDS41_10_15_2021(nA_UGSV, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ09_KDS41_10_15_2021(nA_UGSV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cTL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ10_KDS41_10_15_2021(nA_UGSV, bExistLL, cDL, cCSD, cEPV, cFP, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ11_KDS41_10_15_2021(nA_UGSV, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cTL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ12_KDS41_10_15_2021(nA_UGSV, FALSE, cDL, cCSD, cEPV, cFP, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ13_KDS41_10_15_2021(nA_UGSV, bExistLL, FALSE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ14_KDS41_10_15_2021(nA_UGSV, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ15_KDS41_10_15_2021(nA_UGSV, FALSE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);
    }

    if ( m_bLcomUGSpec )
    {
        m_iSetLcomForKBC = 1;
        Set_PrevLcomSRSS(TRUE, 1.0, 1.0, cEL, cESP);
        Set_PrevLcomSRSS_UGEP(TRUE);

        const int nA_UGSP = nA_SPEC;
        Make_SubComb_EQ01_KDS41_10_15_2021(nA_UGSP, cDL, cCSD, cEPV, cFP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ02_KDS41_10_15_2021(nA_UGSP, cDL, cCSD, cEPV, cFP, cTL, cLL, cCSL, cIL, cLR, cSL, cRL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ03_KDS41_10_15_2021(nA_UGSP, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ04_KDS41_10_15_2021(nA_UGSP, bExistLL, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cLR, cSL, cRL, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ05_KDS41_10_15_2021(nA_UGSP, bExistLL, TRUE, cDL, cCSD, cEPV, cFP, cLL, cCSL, cIL, cSL, cEL, cESP, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ06_KDS41_10_15_2021(nA_UGSP, cDL, cCSD, cEPV, cWL, cPsTs, strPsTs, dPSS);
        Make_SubComb_EQ07_KDS41_10_15_2021(nA_UGSP, TRUE, cDL, cCSD, cEPV, cFP, cEL, cESP, cPsTs, strPsTs, dPSS);
    }

    // Add by ZINU.('05.04.19). Consider SRSS.
    if ( m_nOrthoType==1 )	m_iSetLcomForSRSS = 0;

    m_bModeUG = FALSE;
}

void CLoadCombCtrl::MakeSeisComb_KISTEC2013(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cSL, CombBase* cEL, CombBase* cESP)
{
    MakeGravLoadMapKISTEC(m_aSelGravLoad, m_aEffectiveLoad, m_mapGravSeisEval);

    CombBase* apcLoad[4] = { cDL, cLL, cLR, cSL };
    CString astrSym[4] = { _T("(SGRV)DL"), _T("(SEFL)LL"), _T("(SEFR)LR"), _T("(SEFS)SL") };
    double aFact[4] = { 1.1, 1.1, 1.1, 1.1 };
    CString strDesc = _T("");
    for (int i=0; i<4; ++i)
    {
        if (apcLoad[i]->IsExist())
        {
            if (strDesc.IsEmpty()) strDesc = astrSym[i];
            else                   strDesc += _T(" + ") + astrSym[i];
        }
        else
        {
            aFact[i] = 0.0;
        }
    }

    SetAddSeisLcomParam();
    m_iSetLcomForKBC = 0;
    Set_PrevLcomSRSS(FALSE, 1.0, 1.0, cEL,cESP);

    /// QUD : 변형지배거동 하중조합 기준으로 생성.(Deformation-Controlled Actions)
    int nActGen = 1;
    Set_LCB(nActGen, strDesc + _T(" + EL"),  aFact[0],apcLoad[0], aFact[1],apcLoad[1], aFact[2],apcLoad[2], aFact[3],apcLoad[3],  1.0,cEL);
    Set_LCB(nActGen, strDesc + _T(" - EL"),  aFact[0],apcLoad[0], aFact[1],apcLoad[1], aFact[2],apcLoad[2], aFact[3],apcLoad[3], -1.0,cEL);
    Set_LCB(nActGen, strDesc + _T(" + ESP"), aFact[0],apcLoad[0], aFact[1],apcLoad[1], aFact[2],apcLoad[2], aFact[3],apcLoad[3],  1.0,cESP);
    Set_LCB(nActGen, strDesc + _T(" - ESP"), aFact[0],apcLoad[0], aFact[1],apcLoad[1], aFact[2],apcLoad[2], aFact[3],apcLoad[3], -1.0,cESP);
    Set_LCB(nActGen, _T("(SGRV)DL + EL"),  0.9,apcLoad[0],  1.0,cEL);
    Set_LCB(nActGen, _T("(SGRV)DL - EL"),  0.9,apcLoad[0], -1.0,cEL);
    Set_LCB(nActGen, _T("(SGRV)DL + ESP"), 0.9,apcLoad[0],  1.0,cESP);
    Set_LCB(nActGen, _T("(SGRV)DL - ESP"), 0.9,apcLoad[0], -1.0,cESP);

    if (m_bSlcmVertical)
    {		
        m_iSetLcomForKBC = 2;
        Set_PrevLcomSRSS(FALSE, 1.0, 1.0, cEL,cESP);
        double dDLv = (-1.0)*m_dSlcmVertical;

        int nActVer = 2;
        Set_LCB(nActVer, strDesc + _T(" + EL"),  aFact[0],apcLoad[0], aFact[1],apcLoad[1], aFact[2],apcLoad[2], aFact[3],apcLoad[3],  1.0,cEL);
        Set_LCB(nActVer, strDesc + _T(" - EL"),  aFact[0],apcLoad[0], aFact[1],apcLoad[1], aFact[2],apcLoad[2], aFact[3],apcLoad[3], -1.0,cEL);
        Set_LCB(nActVer, strDesc + _T(" + ESP"), aFact[0],apcLoad[0], aFact[1],apcLoad[1], aFact[2],apcLoad[2], aFact[3],apcLoad[3],  1.0,cESP);
        Set_LCB(nActVer, strDesc + _T(" - ESP"), aFact[0],apcLoad[0], aFact[1],apcLoad[1], aFact[2],apcLoad[2], aFact[3],apcLoad[3], -1.0,cESP);
        Set_LCB(nActVer, _T("(SGRV)DL + EL"),  0.9,apcLoad[0],  1.0,cEL);
        Set_LCB(nActVer, _T("(SGRV)DL - EL"),  0.9,apcLoad[0], -1.0,cEL);
        Set_LCB(nActVer, _T("(SGRV)DL + ESP"), 0.9,apcLoad[0],  1.0,cESP);
        Set_LCB(nActVer, _T("(SGRV)DL - ESP"), 0.9,apcLoad[0], -1.0,cESP);
        Set_LCB(nActVer, _T("-(VER)DL + EL"),  dDLv,apcLoad[0],  1.0,cEL);
        Set_LCB(nActVer, _T("-(VER)DL - EL"),  dDLv,apcLoad[0], -1.0,cEL);
        Set_LCB(nActVer, _T("-(VER)DL + ESP"), dDLv,apcLoad[0],  1.0,cESP);
        Set_LCB(nActVer, _T("-(VER)DL - ESP"), dDLv,apcLoad[0], -1.0,cESP);
    }
}

void CLoadCombCtrl::MakeSeisComb_MOE2018(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cSL, CombBase* cEL, CombBase* cESP)
{
    /// 1단계 상세평가 (m-계수법) 하중조합은 동일.
    MakeSeisComb_KISTEC2013(cDL, cLL, cLR, cSL, cEL, cESP);
}


void CLoadCombCtrl::MakeSeisComb_KISTEC2019(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cSL, CombBase* cEL, CombBase* cESP)
{
    /// 1단계 상세평가 (m-계수법) 하중조합은 동일.
    MakeSeisComb_KISTEC2013(cDL, cLL, cLR, cSL, cEL, cESP);
}

void CLoadCombCtrl::MakeSeisComb_MOE2018_Linear(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cSL, CombBase* cRL, CombBase* cEL, CombBase* cESP)
{
    SetAddSeisLcomParam();
    m_iSetLcomForKBC = 0;
    Set_PrevLcomSRSS(FALSE, 1.0, 1.0, cEL,cESP);

    BOOL bExistLL = cLL->IsExist();

    CString strDesc = _T("");
    /// [5695-46] gravity 조합을 먼저 생성해 주세요.
    int nActGra = 1;  // gravity.
    Set_LCB(nActGra, _T("1.4DL"),  1.4, cDL);

    if (!cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist())
    {
        Set_LCB(nActGra, _T("1.2DL + 1.6LL"), 1.2, cDL, 1.6, cLL);
        Set_LCB(nActGra, _T("1.2DL + 1.0LL"), 1.2, cDL, 1.0, cLL);
    }
    else
    {
        CString strCaseLR[3] = { _T("LR"), _T("SL"), _T("RL") };
        CombBase* cLoadLR[3] = { cLR, cSL, cRL };

        if (bExistLL)
        {
            for(int i=0; i<3; i++)
            {
                strDesc.Format(_T("1.2DL + 1.6LL + 0.5%s"), strCaseLR[i]);
                Set_LCB(nActGra, strDesc, 1.2,cDL, 1.6,cLL, 0.5,cLoadLR[i]);
            }

            for(int i=0; i<3; i++)
            {
                strDesc.Format(_T("1.2DL + 1.0LL + 1.6%s"), strCaseLR[i]);
                Set_LCB(nActGra, strDesc, 1.2,cDL, 1.0,cLL, 1.6,cLoadLR[i]);
            }
        }
        else
        {
            for(int i=0; i<3; i++)
            {
                strDesc.Format(_T("1.2DL + 0.5%s"), strCaseLR[i]);
                Set_LCB(nActGra, strDesc, 1.2,cDL, 0.5,cLoadLR[i]);
            }

            for(int i=0; i<3; i++)
            {
                strDesc.Format(_T("1.2DL + 1.6%s"), strCaseLR[i]);
                Set_LCB(nActGra, strDesc, 1.2,cDL, 1.6,cLoadLR[i]);
            }
        }
    }

    BOOL bExistSL = cSL->IsExist();

    int nActGen = 2;  // general seismic.	
    if (bExistSL)
    {
        if (bExistLL)
        {
            Set_LCB(nActGen, _T("1.2DL + 1.0LL + 1.0EL + 0.2SL"),  1.2, cDL, 1.0,cLL,  1.0,cEL, 0.2,cSL);
            Set_LCB(nActGen, _T("1.2DL + 1.0LL - 1.0EL + 0.2SL"),  1.2, cDL, 1.0,cLL, -1.0,cEL, 0.2,cSL);
            Set_LCB(nActGen, _T("1.2DL + 1.0LL + 1.0ESP + 0.2SL"), 1.2, cDL, 1.0,cLL,  1.0,cESP, 0.2,cSL);
            Set_LCB(nActGen, _T("1.2DL + 1.0LL - 1.0ESP + 0.2SL"), 1.2, cDL, 1.0,cLL, -1.0,cESP, 0.2,cSL);	
        }
        else
        {
            Set_LCB(nActGen, _T("1.2DL + 1.0EL + 0.2SL"),  1.2, cDL,  1.0,cEL, 0.2,cSL);
            Set_LCB(nActGen, _T("1.2DL - 1.0EL + 0.2SL"),  1.2, cDL, -1.0,cEL, 0.2,cSL);
            Set_LCB(nActGen, _T("1.2DL + 1.0ESP + 0.2SL"), 1.2, cDL,  1.0,cESP, 0.2,cSL);
            Set_LCB(nActGen, _T("1.2DL - 1.0ESP + 0.2SL"), 1.2, cDL, -1.0,cESP, 0.2,cSL);	
        }
    }
    else
    {
        if (bExistLL)
        {
            Set_LCB(nActGen, _T("1.2DL + 1.0LL + 1.0EL"),  1.2, cDL, 1.0,cLL,  1.0,cEL);
            Set_LCB(nActGen, _T("1.2DL + 1.0LL - 1.0EL"),  1.2, cDL, 1.0,cLL, -1.0,cEL);
            Set_LCB(nActGen, _T("1.2DL + 1.0LL + 1.0ESP"), 1.2, cDL, 1.0,cLL,  1.0,cESP);
            Set_LCB(nActGen, _T("1.2DL + 1.0LL - 1.0ESP"), 1.2, cDL, 1.0,cLL, -1.0,cESP);			
        }
        else
        {
            Set_LCB(nActGen, _T("1.2DL + 1.0EL"),  1.2, cDL,  1.0,cEL);
            Set_LCB(nActGen, _T("1.2DL - 1.0EL"),  1.2, cDL, -1.0,cEL);
            Set_LCB(nActGen, _T("1.2DL + 1.0ESP"), 1.2, cDL,  1.0,cESP);
            Set_LCB(nActGen, _T("1.2DL - 1.0ESP"), 1.2, cDL, -1.0,cESP);			
        }
    }
    Set_LCB(nActGen, _T("0.9DL + EL"),  0.9,cDL,  1.0,cEL);
    Set_LCB(nActGen, _T("0.9DL - EL"),  0.9,cDL, -1.0,cEL);
    Set_LCB(nActGen, _T("0.9DL + ESP"), 0.9,cDL,  1.0,cESP);
    Set_LCB(nActGen, _T("0.9DL - ESP"), 0.9,cDL, -1.0,cESP);

    if (m_bSlcmSpecial)
    {		
        m_iSetLcomForKBC = 1;
        Set_PrevLcomSRSS(TRUE, 1.0, 1.0, cEL,cESP);

        double dDLp12 = 1.2 + m_dSlcmSds * m_dSlcmSpecial; // for 1.2D +- (OMG)E + 0.2SDS*D 
        double dDLm09 = 0.9 - m_dSlcmSds * m_dSlcmSpecial; // for 0.9D +- (OMG)E + 0.2SDS*D

        int nActSpe = 3;
        if (bExistSL)
        {
            if (bExistLL)
            {
                Set_LCB(nActSpe, _T("1.2DL + 1.0LL + (OMG)EL + (SPC)(SDS)DL + 0.2SL"),  dDLp12, cDL, 1.0,cLL,  1.0,cEL, 0.2,cSL);
                Set_LCB(nActSpe, _T("1.2DL + 1.0LL - (OMG)EL + (SPC)(SDS)DL + 0.2SL"),  dDLp12, cDL, 1.0,cLL, -1.0,cEL, 0.2,cSL);
                Set_LCB(nActSpe, _T("1.2DL + 1.0LL + (SUF)(OMG)ESP + (SPC)(SDS)DL + 0.2SL"), dDLp12, cDL, 1.0,cLL,  1.0,cESP, 0.2,cSL);
                Set_LCB(nActSpe, _T("1.2DL + 1.0LL - (SUF)(OMG)ESP + (SPC)(SDS)DL + 0.2SL"), dDLp12, cDL, 1.0,cLL, -1.0,cESP, 0.2,cSL);
            }
            else
            {
                Set_LCB(nActSpe, _T("1.2DL + (OMG)EL + (SPC)(SDS)DL + 0.2SL"),  dDLp12, cDL,  1.0,cEL, 0.2,cSL);
                Set_LCB(nActSpe, _T("1.2DL - (OMG)EL + (SPC)(SDS)DL + 0.2SL"),  dDLp12, cDL, -1.0,cEL, 0.2,cSL);
                Set_LCB(nActSpe, _T("1.2DL + (SUF)(OMG)ESP + (SPC)(SDS)DL + 0.2SL"), dDLp12, cDL,  1.0,cESP, 0.2,cSL);
                Set_LCB(nActSpe, _T("1.2DL - (SUF)(OMG)ESP + (SPC)(SDS)DL + 0.2SL"), dDLp12, cDL, -1.0,cESP, 0.2,cSL);
            }			
        }
        else
        {
            if (bExistLL)
            {
                Set_LCB(nActSpe, _T("1.2DL + 1.0LL + (OMG)EL + (SPC)(SDS)DL"),  dDLp12, cDL, 1.0,cLL,  1.0,cEL);
                Set_LCB(nActSpe, _T("1.2DL + 1.0LL - (OMG)EL + (SPC)(SDS)DL"),  dDLp12, cDL, 1.0,cLL, -1.0,cEL);
                Set_LCB(nActSpe, _T("1.2DL + 1.0LL + (SUF)(OMG)ESP + (SPC)(SDS)DL"), dDLp12, cDL, 1.0,cLL,  1.0,cESP);
                Set_LCB(nActSpe, _T("1.2DL + 1.0LL - (SUF)(OMG)ESP + (SPC)(SDS)DL"), dDLp12, cDL, 1.0,cLL, -1.0,cESP);
            }
            else
            {
                Set_LCB(nActSpe, _T("1.2DL + (OMG)EL + (SPC)(SDS)DL"),  dDLp12, cDL,  1.0,cEL);
                Set_LCB(nActSpe, _T("1.2DL - (OMG)EL + (SPC)(SDS)DL"),  dDLp12, cDL, -1.0,cEL);
                Set_LCB(nActSpe, _T("1.2DL + (SUF)(OMG)ESP + (SPC)(SDS)DL"), dDLp12, cDL,  1.0,cESP);
                Set_LCB(nActSpe, _T("1.2DL - (SUF)(OMG)ESP + (SPC)(SDS)DL"), dDLp12, cDL, -1.0,cESP);
            }
        }
        Set_LCB(nActSpe, _T("0.9DL + (OMG)EL - (SPC)(SDS)DL"), dDLm09,cDL,  1.0,cEL);
        Set_LCB(nActSpe, _T("0.9DL - (OMG)EL - (SPC)(SDS)DL"),  dDLm09,cDL, -1.0,cEL);
        Set_LCB(nActSpe, _T("0.9DL + (SUF)(OMG)ESP - (SPC)(SDS)DL"), dDLm09,cDL,  1.0,cESP);
        Set_LCB(nActSpe, _T("0.9DL - (SUF)(OMG)ESP - (SPC)(SDS)DL"), dDLm09,cDL, -1.0,cESP);
    }

    if (m_bSlcmVertical)
    {		
        m_iSetLcomForKBC = 2;
        Set_PrevLcomSRSS(FALSE, 1.0, 1.0, cEL,cESP);
        double dDLv = (-1.0)*m_dSlcmVertical;

        int nActVer = 4;
        if (bExistSL)
        {
            if (bExistLL)
            {
                Set_LCB(nActVer, _T("1.2DL + 1.0LL + 1.0EL + 0.2SL"),  1.2, cDL, 1.0,cLL,  1.0,cEL, 0.2,cSL);
                Set_LCB(nActVer, _T("1.2DL + 1.0LL - 1.0EL + 0.2SL"),  1.2, cDL, 1.0,cLL, -1.0,cEL, 0.2,cSL);
                Set_LCB(nActVer, _T("1.2DL + 1.0LL + 1.0ESP + 0.2SL"), 1.2, cDL, 1.0,cLL,  1.0,cESP, 0.2,cSL);
                Set_LCB(nActVer, _T("1.2DL + 1.0LL - 1.0ESP + 0.2SL"), 1.2, cDL, 1.0,cLL, -1.0,cESP, 0.2,cSL);	
            }
            else
            {
                Set_LCB(nActVer, _T("1.2DL + 1.0EL + 0.2SL"),  1.2, cDL,  1.0,cEL, 0.2,cSL);
                Set_LCB(nActVer, _T("1.2DL - 1.0EL + 0.2SL"),  1.2, cDL, -1.0,cEL, 0.2,cSL);
                Set_LCB(nActVer, _T("1.2DL + 1.0ESP + 0.2SL"), 1.2, cDL,  1.0,cESP, 0.2,cSL);
                Set_LCB(nActVer, _T("1.2DL - 1.0ESP + 0.2SL"), 1.2, cDL, -1.0,cESP, 0.2,cSL);	
            }
        }
        else
        {
            if (bExistLL)
            {
                Set_LCB(nActVer, _T("1.2DL + 1.0LL + 1.0EL"),  1.2, cDL, 1.0,cLL,  1.0,cEL);
                Set_LCB(nActVer, _T("1.2DL + 1.0LL - 1.0EL"),  1.2, cDL, 1.0,cLL, -1.0,cEL);
                Set_LCB(nActVer, _T("1.2DL + 1.0LL + 1.0ESP"), 1.2, cDL, 1.0,cLL,  1.0,cESP);
                Set_LCB(nActVer, _T("1.2DL + 1.0LL - 1.0ESP"), 1.2, cDL, 1.0,cLL, -1.0,cESP);	
            }
            else
            {
                Set_LCB(nActVer, _T("1.2DL + 1.0EL"),  1.2, cDL,  1.0,cEL);
                Set_LCB(nActVer, _T("1.2DL - 1.0EL"),  1.2, cDL, -1.0,cEL);
                Set_LCB(nActVer, _T("1.2DL + 1.0ESP"), 1.2, cDL,  1.0,cESP);
                Set_LCB(nActVer, _T("1.2DL - 1.0ESP"), 1.2, cDL, -1.0,cESP);	
            }
        }
        Set_LCB(nActVer, _T("0.9DL + EL"),  0.9,cDL,  1.0,cEL);
        Set_LCB(nActVer, _T("0.9DL - EL"),  0.9,cDL, -1.0,cEL);
        Set_LCB(nActVer, _T("0.9DL + ESP"), 0.9,cDL,  1.0,cESP);
        Set_LCB(nActVer, _T("0.9DL - ESP"), 0.9,cDL, -1.0,cESP);
        Set_LCB(nActVer, _T("-(VER)DL + EL"),  dDLv,cDL,  1.0,cEL);
        Set_LCB(nActVer, _T("-(VER)DL - EL"),  dDLv,cDL, -1.0,cEL);
        Set_LCB(nActVer, _T("-(VER)DL + ESP"), dDLv,cDL,  1.0,cESP);
        Set_LCB(nActVer, _T("-(VER)DL - ESP"), dDLv,cDL, -1.0,cESP);
    }
}

////////////////////////////////////////////////////////////////////////////
// Add by GAY. PMS:4215. ('11.01.17). Load Combination for JUD.
////////////////////////////////////////////////////////////////////////////
void CLoadCombCtrl::MakeComb_JUD(CombBase* cDL, CombBase* cLL, CombBase* cLR, CombBase* cSL, CombBase* cWLX, CombBase* cWLY, CombBase* cELX, CombBase* cELY, 
                                 CombBase* cPS, CombBase* cESPX, CombBase* cESPY, CombBase* cCSD, CombBase* cCSL)
{
    //==========================================
    // See 건축구조 Pocket Book (제5판), p.96.
    //==========================================
    double dSF = 1.0;
    int nA = 1 + m_nConstLoad*100;

    if(m_nConstLoad==0) // ST Only.
    {
        cCSD = NULL;
        cCSL = NULL;
    }
    else if(m_nConstLoad==1) // CS Only.
    {
        cDL = NULL;
        cLL = NULL;
    }

    //========================================================================
    //$!// DB 연결 후, 변수 Setting 필요.
    T_JDLS_D JdlsD;  JdlsD.Initialize();
    if(!m_pDoc->m_pAttrCtrl2->GetJdls(JdlsD)) JdlsD.Initialize();

    // Add by GAY. PMS:4215-195. ('12.01.04). 계산정보>하중&응력>응력계산정보>수평하중의 방향 활성화.
    // Add/Modify by Seungjun '20120905 옵션삭제
    BOOL bHorzXPlus = TRUE;//(JdlsD.nStrsXPos == 1)? FALSE : TRUE;
    BOOL bHorzXMins = TRUE;//(JdlsD.nStrsXPos == 0)? FALSE : TRUE;
    BOOL bHorzYPlus = TRUE;//(JdlsD.nStrsYPos == 1)? FALSE : TRUE;
    BOOL bHorzYMins = TRUE;//(JdlsD.nStrsYPos == 0)? FALSE : TRUE;
    //   BOOL bHorzXPlus, bHorzXMins, bHorzYPlus, bHorzYMins;	
    // 
    // 	if(JdlsD.nShortLcom == 0)
    // 	{
    // 		bHorzXPlus = bHorzXMins = bHorzYPlus = bHorzYMins = TRUE; // [4215-124] MQC(Alpha/Beta) 요청사항 
    // 	}
    // 	else 
    // 	{
    // 		ASSERT(0); // 비선형(인장트러스, 압축트러스등) 일때에만 정방향 역방향 하중조합값이 차이 가 있으므로 의미가 있으며 
    // 		           // [중요!!!] 또한 하중조합을 하나의 하중으로 치환시켜 해석을 수행시키는 작업이 추가적으로 필요 합니다.
    // 		bHorzXPlus = (JdlsD.nStrsXPos == 0 || JdlsD.nStrsXPos == 2);  // 계산정보>하중&응력>응력계산정보>수평하중의 방향>X방향>정방향 또는 양방향 선택시, TRUE.
    // 		bHorzXMins = (JdlsD.nStrsXPos == 1 || JdlsD.nStrsXPos == 2);  // 계산정보>하중&응력>응력계산정보>수평하중의 방향>X방향>부방향 또는 양방향 선택시, TRUE.
    // 		bHorzYPlus = (JdlsD.nStrsYPos == 0 || JdlsD.nStrsYPos == 2);  // 계산정보>하중&응력>응력계산정보>수평하중의 방향>Y방향>정방향 또는 양방향 선택시, TRUE.
    // 		bHorzYMins = (JdlsD.nStrsYPos == 1 || JdlsD.nStrsYPos == 2);  // 계산정보>하중&응력>응력계산정보>수평하중의 방향>Y방향>부방향 또는 양방향 선택시, TRUE.
    // 	}

    int nSnowCombType = 0;
    if(cSL->m_arLd.GetSize() > 0)
    { nSnowCombType = JdlsD.bSnowFactor ? 2 : 1; }   // 0=고려하지 않음. 1=일반지역, 2=다설지역.
    double dLongS   = JdlsD.dSnowFactor_LT;  // in SS3, Delta1. (설하중 입력정보)
    double dShortSE = JdlsD.dSnowFactor_EL;  // in SS3, Delta2. (설하중 입력정보)
    double dShortSW = JdlsD.dSnowFactor_WL;  // in SS3, Delta3. (설하중 입력정보)
    //========================================================================


    BOOL bDL = ((cDL==NULL?FALSE:cDL->IsExist()) || (cCSD==NULL?FALSE:cCSD->IsExist()));
    BOOL bLL = ((cLL==NULL?FALSE:cLL->IsExist()) || (cCSL==NULL?FALSE:cCSL->IsExist()) || (cLR==NULL?FALSE:cLR->IsExist()));

    // [G+P]
    Set_LCB_JUD(nA, bDL, bLL, "DL + (LL+LR) + PS", 1.0, cDL, 1.0, cCSD, 1.0, cLL, 1.0, cCSL, 1.0, cLR, 1.0, cPS);
    if(m_nLcomType == D_LCOMTYPE_GENERAL) return; // General 에 D+L만 추가시켜달라고 요청함 2011.09.05 - Midas-JP, 윤태영

    if(nSnowCombType==1)
    {
        // [G+P+S]
        Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + SL + PS"), 1.0, cDL, 1.0, cCSD, 1.0, cLL, 1.0, cCSL, 1.0, cLR, 1.0, cSL, 1.0, cPS);
    }
    else if(nSnowCombType==2)
    {
        // Modify by GAY. PMS:4215-126. ('12.01.04). 장기적설하중은 이번버전에서 제외.
        // [G+P+0.7S]
        //Set_LCB_JUD(nA, bDL, bLL, "DL + (LL+LR) + (Delta1)SL + PS", 1.0, cDL, 1.0, cCSD, 1.0, cLL, 1.0, cCSL, 1.0, cLR, dLongS, cSL, 1.0, cPS);
        // [G+P+S]
        Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + SL + PS"),         1.0, cDL, 1.0, cCSD, 1.0, cLL, 1.0, cCSL, 1.0, cLR,    1.0, cSL, 1.0, cPS);    
    }

    // [G+P+W] for Wind Load Case.
    if(bHorzXPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + WL + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR,      dSF, cWLX, 1.0, cPS);
    if(bHorzXMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) - WL + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, -1.0*dSF, cWLX, 1.0, cPS);
    if(bHorzYPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + WL + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR,      dSF, cWLY, 1.0, cPS);
    if(bHorzYMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) - WL + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, -1.0*dSF, cWLY, 1.0, cPS);

    if(nSnowCombType==2)
    {
        // [G+P+0.35S+W] for Wind Load Case.
        if(bHorzXPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta3)SL + WL + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSW, cSL,      dSF, cWLX, 1.0, cPS);
        if(bHorzXMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta3)SL - WL + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSW, cSL, -1.0*dSF, cWLX, 1.0, cPS);
        if(bHorzYPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta3)SL + WL + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSW, cSL,      dSF, cWLY, 1.0, cPS);
        if(bHorzYMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta3)SL - WL + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSW, cSL, -1.0*dSF, cWLY, 1.0, cPS);
    }

    if(nSnowCombType==0 || nSnowCombType==1)
    {
        // [G+P+K] for Static Seismic Load Case.
        if(bHorzXPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + EL + PS"),       dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR,      dSF, cELX, 1.0, cPS);
        if(bHorzXMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) - EL + PS"),       dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, -1.0*dSF, cELX, 1.0, cPS);
        if(bHorzYPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + EL + PS"),       dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR,      dSF, cELY, 1.0, cPS);
        if(bHorzYMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) - EL + PS"),       dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, -1.0*dSF, cELY, 1.0, cPS);

        // [G+P+K] for Response Spectrum Load Case.
        if(bHorzXPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (SUF)ESP + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR,      dSF, cESPX, 1.0, cPS);
        if(bHorzXMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) - (SUF)ESP + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, -1.0*dSF, cESPX, 1.0, cPS);
        if(bHorzYPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (SUF)ESP + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR,      dSF, cESPY, 1.0, cPS);
        if(bHorzYMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) - (SUF)ESP + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, -1.0*dSF, cESPY, 1.0, cPS);
    }
    else if(nSnowCombType==2)
    {
        // [G+P+0.35S+K] for Static Seismic Load Case.
        if(bHorzXPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta2)SL + EL + PS"),       dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSE, cSL,     dSF, cELX, 1.0, cPS);
        if(bHorzXMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta2)SL - EL + PS"),       dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSE, cSL,-1.0*dSF, cELX, 1.0, cPS);
        if(bHorzYPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta2)SL + EL + PS"),       dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSE, cSL,     dSF, cELY, 1.0, cPS);
        if(bHorzYMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta2)SL - EL + PS"),       dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSE, cSL,-1.0*dSF, cELY, 1.0, cPS);

        // [G+P+0.35S+K] for Response Spectrum Load Case.
        if(bHorzXPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta2)SL + (SUF)ESP + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSE, cSL,     dSF, cESPX, 1.0, cPS);
        if(bHorzXMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta2)SL - (SUF)ESP + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSE, cSL,-1.0*dSF, cESPX, 1.0, cPS);
        if(bHorzYPlus) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta2)SL + (SUF)ESP + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSE, cSL,     dSF, cESPY, 1.0, cPS);
        if(bHorzYMins) Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + (Delta2)SL - (SUF)ESP + PS"), dSF, cDL, dSF, cCSD, dSF, cLL, dSF, cCSL, dSF, cLR, dShortSE, cSL,-1.0*dSF, cESPY, 1.0, cPS);
    }

    if(m_nLcomType == D_LCOMTYPE_STEEL || m_nLcomType == D_LCOMTYPE_CONCRETE)
    {
        nA = 2 + m_nConstLoad*100;
        Set_LCB_JUD(nA, bDL, bLL, _T("DL + (LL+LR) + PS"), 1.0, cDL, 1.0, cCSD, 1.0, cLL, 1.0, cCSL, 1.0, cLR, 1.0, cPS);
    }
}

