void CLoadCombCtrl::Set_LCB(int nAcitve, CString strReport, const std::vector<std::pair<double, CombBase*>>& vCombBase)
{
	CArray<CombBase, CombBase> arLcase;
	CArray<double, double> adFactor;
    for (const auto& pair : vCombBase)
    {
        if (pair.first != 0.0 && pair.second != NULL && pair.second->IsExist())
        {
            adFactor.Add(pair.first);
            arLcase.Add(*pair.second);
        }
	}
	if (adFactor.GetSize() > 0)	Make_LoadCombination(strReport, adFactor, arLcase, nAcitve);
}

