void CLoadCombCtrl::Set_LCB_JUD(int nAcitve, BOOL bDL, BOOL bLL, CString strReport, double dFac01, CombBase* pLoad01,
                                double dFac02, CombBase* pLoad02,
                                double dFac03, CombBase* pLoad03,
                                double dFac04, CombBase* pLoad04,
                                double dFac05, CombBase* pLoad05,
                                double dFac06, CombBase* pLoad06,
                                double dFac07, CombBase* pLoad07,
                                double dFac08, CombBase* pLoad08,
                                double dFac09, CombBase* pLoad09,
                                double dFac10, CombBase* pLoad10,
                                double dFac11, CombBase* pLoad11,
                                double dFac12, CombBase* pLoad12,
                                double dFac13, CombBase* pLoad13,
                                double dFac14, CombBase* pLoad14,
                                double dFac15, CombBase* pLoad15,
                                double dFac16, CombBase* pLoad16,
                                double dFac17, CombBase* pLoad17,
                                double dFac18, CombBase* pLoad18,
                                double dFac19, CombBase* pLoad19,
                                double dFac20, CombBase* pLoad20,
                                double dFac21, CombBase* pLoad21,
                                double dFac22, CombBase* pLoad22)
{
    if(!bDL) { strReport.Replace(_T(" + DL"), _T(""));  strReport.Replace(_T(" - DL"), _T(""));  strReport.Replace(_T("DL"), _T("")); }
    if(!bLL) { strReport.Replace(_T(" + (LL+LR)"), _T(""));  strReport.Replace(_T(" - (LL+LR)"), _T(""));  strReport.Replace(_T("(LL+LR)"), _T(""));}
    if(!bDL || !bLL)
    {
        strReport.TrimLeft();
        int nSize = strReport.GetLength();
        if(nSize > 0)
        {
            if(strReport[0] == '+')
            { 
                strReport = strReport.Right(nSize-1); 
                strReport.TrimLeft();
            }
        }
    }

    CArray<CombBase,CombBase> arLcase;
    CArray<double,double> adFactor;
    double dFactor;
    CombBase * pLcase;
    for(int i=1 ; i<=22 ; i++)
    {
        if     (i== 1) {dFactor=dFac01;  pLcase=pLoad01; }
        else if(i== 2) {dFactor=dFac02;  pLcase=pLoad02; }
        else if(i== 3) {dFactor=dFac03;  pLcase=pLoad03; }
        else if(i== 4) {dFactor=dFac04;  pLcase=pLoad04; }
        else if(i== 5) {dFactor=dFac05;  pLcase=pLoad05; }
        else if(i== 6) {dFactor=dFac06;  pLcase=pLoad06; }
        else if(i== 7) {dFactor=dFac07;  pLcase=pLoad07; }
        else if(i== 8) {dFactor=dFac08;  pLcase=pLoad08; }
        else if(i== 9) {dFactor=dFac09;  pLcase=pLoad09; }
        else if(i==10) {dFactor=dFac10;  pLcase=pLoad10; }
        else if(i==11) {dFactor=dFac11;  pLcase=pLoad11; }
        else if(i==12) {dFactor=dFac12;  pLcase=pLoad12; }
        else if(i==13) {dFactor=dFac13;  pLcase=pLoad13; }
        else if(i==14) {dFactor=dFac14;  pLcase=pLoad14; }
        else if(i==15) {dFactor=dFac15;  pLcase=pLoad15; }
        else if(i==16) {dFactor=dFac16;  pLcase=pLoad16; }
        else if(i==17) {dFactor=dFac17;  pLcase=pLoad17; }
        else if(i==18) {dFactor=dFac18;  pLcase=pLoad18; }
        else if(i==19) {dFactor=dFac19;  pLcase=pLoad19; }
        else if(i==20) {dFactor=dFac20;  pLcase=pLoad20; }
        else if(i==21) {dFactor=dFac21;  pLcase=pLoad21; }
        else if(i==22) {dFactor=dFac22;  pLcase=pLoad22; }
        else break;

        if(dFactor!=0.0 && pLcase!=NULL) 
        {
            if(!bDL && pLcase->m_strType == "DL") continue;
            if(!bLL && (pLcase->m_strType == "LL" || pLcase->m_strType == "LR")) continue;
            adFactor.Add(dFactor); arLcase.Add(*pLcase);
        }
    }

    if(adFactor.GetSize() > 0)	Make_LoadCombination(strReport,adFactor,arLcase,nAcitve);
}

// Add by ZINU.('05.06.20). Consider Omega (See CDgnDataCtrl::Get_SpecialLcomOmega()).
BOOL CLoadCombCtrl::Get_SpecialLcomOmega(int iLcasNo, int iAnalType, double& dOmega)
{
    double dSubOmega=1.0;
    if(iAnalType==D_LCOM_STATIC)						m_arSlcfStldK.Lookup(iLcasNo,dSubOmega);
    else if(iAnalType==D_LCOM_SPECTRUM)			m_arSlcfSplcK.Lookup(iLcasNo,dSubOmega);
    else if(iAnalType==D_LCOM_ECCENSPEC)		m_arSlcfSplcK.Lookup(iLcasNo,dSubOmega);
    else if(iAnalType==D_LCOM_CB_GENERAL || iAnalType==D_LCOM_CB_STEEL || iAnalType==D_LCOM_CB_CONCRETE || iAnalType==D_LCOM_CB_SRC)
    {
        int iLcomType=0;
        if(iAnalType==D_LCOM_CB_GENERAL)				iLcomType = D_LCOMTYPE_GENERAL;
        else if(iAnalType==D_LCOM_CB_STEEL)			iLcomType = D_LCOMTYPE_STEEL;
        else if(iAnalType==D_LCOM_CB_CONCRETE)	iLcomType = D_LCOMTYPE_CONCRETE;
        else if(iAnalType==D_LCOM_CB_SRC)				iLcomType = D_LCOMTYPE_SRC;
        else	ASSERT(0);
        T_LCOM_D LcomD;
        if(m_pDoc->m_pAttrCtrl->GetLcom(iLcomType,iLcasNo,LcomD))
        {
            for(int i=0; i<LcomD.aCombination.GetSize(); i++)
            {
                T_LCOM_BASE& rLcomBase = LcomD.aCombination[i];
                int iSubLcaseKey = rLcomBase.LoadCaseKey;
                int iSubAnalType = rLcomBase.AnalType;
                if(iSubLcaseKey==0)	break;
                if(!Get_SpecialLcomOmega(iSubLcaseKey, iSubAnalType, dSubOmega))	break;
                dSubOmega = max(dOmega, dSubOmega);
            }
        }
    }
    else	ASSERT(0);
    // Compare Omega.
    dOmega = max(dOmega, dSubOmega);

    return TRUE;
}

// Add by ZINU.('05.04.20). Consider SRSS.
void CLoadCombCtrl::Set_SRSS(double dMainFactor, double dSubFactor)
{
    if(dMainFactor*dSubFactor==0)
    {
        ASSERT(0);
        return;
    }
    const int iAnalType = Get_AnalType(m_nLcomType);
    // Set SRSS.
    int iDirNum = m_arDirLcaseNa.GetCount();
    int iCount=0;
    T_LCOM_D LcomD, PartLcomD;
    int iSta = 0;
    int iEnd = (fabs(dMainFactor-dSubFactor) < m_dZeroLim ? 1 : 2);
    for(int m=iSta; m<iEnd; m++)
    {
        int i1st = (m==0 ? 0 : 1);
        int i2nd = (m==0 ? 1 : 0);
        for(int i=0; i<iDirNum; i++)
        {
            _LCASE_DIR LcaseDir;
            if ( !m_arDirLcaseNa.Lookup(i, LcaseDir) ) { continue; }
            int iLcase1Num = LcaseDir.arLcaseNa[i1st].GetSize();
            int iLcase2Num = LcaseDir.arLcaseNa[i2nd].GetSize();
            
            for(int j=0; j<iLcase1Num; j++)
            {
                LcomD.Initialize();
                // X-Dir.
                CString strLcomNa1 = LcaseDir.arLcaseNa[i1st].GetAt(j);
                PartLcomD.Initialize();
                m_pDoc->m_pAttrCtrl->GetLcom(m_nLcomType, strLcomNa1, PartLcomD);
                CString strSrss1Na = PartLcomD.LoadCombName;
                T_LCOM_BASE LcomBase; LcomBase.Initialize();
                LcomBase.AnalType	= iAnalType;
                LcomBase.Factor		= dMainFactor;
                LcomBase.LoadCaseKey = m_pDoc->m_pAttrCtrl->GetLcomKey(m_nLcomType, strSrss1Na);
                if ( LcomD.aCombination.GetSize() > i1st )
                {
                    LcomD.aCombination[i1st] = LcomBase;
                }
                else
                {
                    LcomD.aCombination.Add(LcomBase);
                }

                if ( fabs(dMainFactor-1.0) > m_dZeroLim )
                {
                    strSrss1Na = GetFactorString(dMainFactor) + strSrss1Na;
                }
                
                for(int k=0; k<iLcase2Num; k++)
                {
                    // Y-Dir.
                    CString strLcomNa2 = LcaseDir.arLcaseNa[i2nd].GetAt(k);
                    PartLcomD.Initialize();
                    m_pDoc->m_pAttrCtrl->GetLcom(m_nLcomType, strLcomNa2, PartLcomD);
                    CString strSrss2Na = PartLcomD.LoadCombName;
                    LcomBase.Initialize();
                    LcomBase.AnalType	= iAnalType;
                    LcomBase.Factor		= dSubFactor;
                    LcomBase.LoadCaseKey = m_pDoc->m_pAttrCtrl->GetLcomKey(m_nLcomType, strSrss2Na);
					if (Is_ChinaCode())
					{
						if(LcomD.aCombination.GetSize() > 1) LcomD.aCombination[i2nd] = LcomBase;
						else LcomD.aCombination.Add(LcomBase);
					}
					else
					{
						if(LcomD.aCombination.GetSize() > i2nd) LcomD.aCombination[i2nd] = LcomBase;
						else LcomD.aCombination.Add(LcomBase);
					}

                    if ( fabs(dSubFactor-1.0) > m_dZeroLim )
                    {
                        strSrss2Na = GetFactorString(dSubFactor) + strSrss2Na;
                    }
                    // Combination by SRSS.
                    LcomD.Description = _T("SQRT[ ") + strSrss1Na + _T("^2 + ") + strSrss2Na + _T("^2 ]");
                    BOOL bTemp = FALSE;
                    Set_LoadComb(iCount, LcomD, bTemp);
                    iCount++;
                }
            }
        }
    }
}

// Add by ZINU.('02.12.18).	To fix figure under point automatically.
BOOL CLoadCombCtrl::Get_RealLcaseFactor(double dFactor, CString sFactor, CString& strTxt)
{
    // MQC 10491 : Static load case 이름에 %가 들어있는 경우, CString::Format() 함수에서 오작동을 일으키는 문제
    strTxt.Replace(CString(_T("%")), CString(_T("%%")));

    CString strFix=_T("");
    if((int)floor(fabs(dFactor)*1000)%10 > 0)			strFix = _T("%.3f");
    else if((int)floor(fabs(dFactor)*100)%10 > 0)	strFix = _T("%.2f");
    else																					strFix = _T("%.1f");
    CString strTempTxt = strTxt;
    int n = strTempTxt.Replace(sFactor, strFix);	// ex) sFactor="SFAC".
    if(n!=0)
    {
        CString strResTxt=_T("");
        strResTxt.Format(strTempTxt, dFactor);
        strTxt = strResTxt;
    }
    if(strTxt==_T(""))	return FALSE;
    else						return TRUE;
}

// Add by ZINU.('02.12.18).	To fix figure under point automatically.
BOOL CLoadCombCtrl::Get_RealLcaseName(const CString& sOrgLcNa, const CString& sCngLcNa, CString& strTxt)
{
    CString strTempTxt = strTxt;
    if(strTempTxt.Find(sOrgLcNa) >= 0)
    {
        strTempTxt.Replace(sOrgLcNa, sCngLcNa);	// ex) sOrgLcNa="ESP".
        strTxt = strTempTxt;
        return TRUE;
    }
    else	return FALSE;
}

// Coded by Seungjun MNet:No.2532 ('20061025)
// If the Orthogonal effect option is checked, check this function.
// Checking the 2nd term of the Case of Over-strength factor.
BOOL CLoadCombCtrl::IsExistedLcase(unsigned int Lcase, CombBase& cLoad, BOOL IsStatic/*=TRUE*/)
{
    if(IsStatic)
    {
        CArray<int,int> arLcase; arLcase.RemoveAll();
        arLcase.Copy(cLoad.m_arLd);
        int iCount = arLcase.GetSize();
        for(int i=0; i<iCount; i++)
        {
            unsigned int LcKey = (unsigned int)arLcase.GetAt(i);
            if(LcKey == Lcase)  return TRUE;
        }
    }
    else
    {
        CArray<unsigned int,unsigned int> arLcase; arLcase.RemoveAll();
        arLcase.Copy(cLoad.m_arLdu);
        int iCount = arLcase.GetSize();
        for(int i=0; i<iCount; i++)
        {
            unsigned int LcKey = arLcase.GetAt(i);
            if(LcKey == Lcase)  return TRUE;
        }  
    }  

    return FALSE;
}

