// Coded by Seungjun MNet:No.2532 ('20061027)
void CLoadCombCtrl::Check_OrthonalCases(CombBase& cEL, CombBase& cEVT, CombBase& cESP, CombBase& cESV, CombBase& cESPE)
{
    BOOL bChinaCode = Is_ChinaCode();

    T_LCOE_D LcoeD;
    LcoeD.Initialize();
    if(m_pDoc->m_pAttrCtrl->GetLcoe(LcoeD))
    {
        BOOL bClearPre = TRUE;
        for(int j=0; j<LcoeD.aLoadCombination.GetSize(); j++)
        {
            BOOL IsExistX = FALSE;
            BOOL IsExistY = FALSE;

            T_LCOE_BASE LcoeBase = LcoeD.aLoadCombination.GetAt(j);

            if(!LcoeBase.nLoadCaseType) // static
            {
                int iCount = cEL.m_arLd.GetSize();
                for(int i=0; i<iCount; i++)
                {
                    if(LcoeBase.StldKdX == cEL.m_arLd.GetAt(i)) IsExistX = TRUE;
                    if(LcoeBase.StldKdY == cEL.m_arLd.GetAt(i)) IsExistY = TRUE;
                }
                BOOL bChkOK = (!IsExistX || !IsExistY) ? FALSE : TRUE;
                if(!bChinaCode && !bChkOK)
                {
                    iCount = cEVT.m_arLd.GetSize();
                    for(int i=0; i<iCount; i++)
                    {
                        if(LcoeBase.StldKdX == cEVT.m_arLd.GetAt(i)) IsExistX = TRUE;
                        if(LcoeBase.StldKdY == cEVT.m_arLd.GetAt(i)) IsExistY = TRUE;
                    }
                }
            }
            else
            {
                int iCount = cESP.m_arLdu.GetSize();
                for(int i=0; i<iCount; i++)
                {
                    if(LcoeBase.StldKdX == cESP.m_arLdu.GetAt(i)) IsExistX = TRUE;
                    if(LcoeBase.StldKdY == cESP.m_arLdu.GetAt(i)) IsExistY = TRUE;
                }      
                BOOL bChkOK = (!IsExistX || !IsExistY) ? FALSE : TRUE;
                if(!bChinaCode && !bChkOK)
                {
                    iCount = cESV.m_arLd.GetSize();
                    for(int i=0; i<iCount; i++)
                    {
                        if(LcoeBase.StldKdX == cESV.m_arLd.GetAt(i)) IsExistX = TRUE;
                        if(LcoeBase.StldKdY == cESV.m_arLd.GetAt(i)) IsExistY = TRUE;
                    }
                }
            }

            if(!IsExistX && !IsExistY)
            {
                CString strError=_T(""), strXLcase=_T(""), strYLcase=_T("");
                if(!LcoeBase.nLoadCaseType) // static
                {
                    strXLcase = Get_StaticLoadCaseName(LcoeBase.StldKdX);
                    strYLcase = Get_StaticLoadCaseName(LcoeBase.StldKdY);
                }
                else
                {
                    strXLcase = Get_SpectrumLoadCaseName(LcoeBase.StldKdX);
                    strYLcase = Get_SpectrumLoadCaseName(LcoeBase.StldKdY);
                }
                strError.Format(_LS(IDS_WG_CMD__ADDD__Warning_Orthogonal_loadcases), strXLcase, strYLcase);
                Write_GDisplayAnalString(strError, bClearPre, FALSE);
                bClearPre=FALSE;
            }
            else if(!IsExistX && IsExistY)
            {
                CString strError=_T(""), strXLcase=_T("");
                if(!LcoeBase.nLoadCaseType) // static
                {
                    strXLcase = Get_StaticLoadCaseName(LcoeBase.StldKdX);
                }
                else
                {
                    strXLcase = Get_SpectrumLoadCaseName(LcoeBase.StldKdX);
                }
                strError.Format(_LS(IDS_WG_CMD__ADDD__Warning_Orthogonal_loadcase), strXLcase);
                Write_GDisplayAnalString(strError, bClearPre, FALSE);
                bClearPre=FALSE;
            }
            else if(IsExistX && !IsExistY)
            {
                CString strError=_T(""), strYLcase=_T("");
                if(!LcoeBase.nLoadCaseType) // static
                {
                    strYLcase = Get_StaticLoadCaseName(LcoeBase.StldKdY);
                }
                else
                {
                    strYLcase = Get_SpectrumLoadCaseName(LcoeBase.StldKdY);
                }
                strError.Format(_LS(IDS_WG_CMD__ADDD__Warning_Orthogonal_loadcase), strYLcase);
                Write_GDisplayAnalString(strError, bClearPre, FALSE);
                bClearPre=FALSE;
            }
        }
    }
}

