void CLoadCombCtrl::Make_SubComb_EQ9_6_ACI318_11(int nA, BOOL bStageCS, double dPSS,
                                                 CombBase* cDL, CombBase* cCSD, CombBase* cWL, CombBase* cEPH, CombBase* cWP, CombBase* cPSorTs, 
                                                 BOOL bSlcmSpecial, BOOL bSlcmVertical)
{
    // [9-6] U = 0.9D+1.0W.
    int nActive = GetActiveIndex(nA, bSlcmSpecial, bSlcmVertical);

    CString strPS   = bStageCS? _T("TS") : _T("PS");
    CString strDesc = _T("");

    const double dWL = m_nWindLoadLevel==D_LOAD_LEVEL_STRN? 1.0 : 1.6;
    double dSP = 0.0;
    CString strLSP = _T("");
    if ( IsConsiderLateralSoil(cEPH, cWP) )
    {
        dSP = m_dLateralSoilFactor;
        strLSP = _T("+ (LSPF)(EH+WP) ");
    }

    // In case of m_bLateralSoil==FALSE, Set m_dLateralSoilFactor=0.0 in Initialize();
    if(!cWL->IsExist())
    {
        strDesc.Format(_T("0.9DL %s+ (SFAC)%s"), strLSP, strPS); 
        Set_LCB(nActive, strDesc,	0.9,cDL, 0.9,cCSD, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);    
    }
    else
    {
        strDesc.Format(_T("0.9DL + %.1fWL %s+ (SFAC)%s"), dWL, strLSP, strPS);
        Set_LCB(nActive, strDesc, 0.9,cDL, 0.9,cCSD,  dWL,cWL, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
        strDesc.Format(_T("0.9DL - %.1fWL %s+ (SFAC)%s"), dWL, strLSP, strPS);
        Set_LCB(nActive, strDesc, 0.9,cDL, 0.9,cCSD, -dWL,cWL, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
    }  
}

void CLoadCombCtrl::Make_SubComb_EQ9_7_ACI318_11(int nA, BOOL bStageCS, double dPSS, 
                                                 CombBase* cDL, CombBase* cCSD, CombBase* cFP, CombBase* cEL, CombBase* cESP, CombBase* cEPH, CombBase* cWP, CombBase* cPSorTs, 
                                                 BOOL bSlcmSpecial, BOOL bSlcmVertical)
{
    // [9-7] U = 0.9D+1.0E
    int nActive = GetActiveIndex(nA, bSlcmSpecial, bSlcmVertical);

    CString strPS   = bStageCS? _T("TS") : _T("PS");
    CString strDesc = _T("");

    double dEL = m_nSeisLoadLevel==D_LOAD_LEVEL_STRN? 1.0 : 1.4;
    double dDLm9 = 0.9 - m_dSlcmSds * m_dSlcmSpecial; // for 0.9D + [(OMG)E - 0.2SDS*D]    

    const double dWL = m_nWindLoadLevel==D_LOAD_LEVEL_STRN? 1.0 : 1.6;
    double dSP = 0.0;
    CString strLSP = _T("");
    if ( IsConsiderLateralSoil(cEPH, cWP) )
    {
        dSP = m_dLateralSoilFactor;
        strLSP = _T("+ (LSPF)(EH+WP) ");
    }

    if(!cEL->IsExist() && !cESP->IsExist())
    {
        strDesc.Format(_T("0.9(DL+FP) %s+ (SFAC)%s"), strLSP, strPS);
        Set_LCB(nActive, strDesc, 0.9,cDL, 0.9,cCSD, 0.9,cFP, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
    }
    else
    {
        if(!bSlcmSpecial)
        {
            strDesc.Format(_T("0.9(DL+FP) + %.1fEL %s+ (SFAC)%s"), dEL, strLSP, strPS); 
            Set_LCB(nActive, strDesc, 0.9,cDL, 0.9,cCSD, 0.9,cFP, dEL,cEL,  dSP,cEPH, dSP,cWP, dPSS,cPSorTs);

            strDesc.Format(_T("0.9(DL+FP) - %.1fEL %s+ (SFAC)%s"), dEL, strLSP, strPS);
            Set_LCB(nActive, strDesc, 0.9,cDL, 0.9,cCSD, 0.9,cFP,-dEL,cEL,  dSP,cEPH, dSP,cWP, dPSS,cPSorTs);

            strDesc.Format(_T("0.9(DL+FP) + %.1f(SUF)ESP %s+ (SFAC)%s"), dEL, strLSP, strPS);
            Set_LCB(nActive, strDesc, 0.9,cDL, 0.9,cCSD, 0.9,cFP, dEL,cESP, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);

            strDesc.Format(_T("0.9(DL+FP) - %.1f(SUF)ESP %s+ (SFAC)%s"), dEL, strLSP, strPS); 
            Set_LCB(nActive, strDesc, 0.9,cDL, 0.9,cCSD, 0.9,cFP,-dEL,cESP, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
        }
        else
        {
            strDesc.Format(_T("0.9(DL+FP) + %.1f(OMG)EL %s+ (SFAC)%s - (SPC)(SDS)DL"), dEL, strLSP, strPS);
            Set_LCB(nActive, strDesc, dDLm9,cDL, dDLm9,cCSD, 0.9,cFP, dEL,cEL,  dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
            
            strDesc.Format(_T("0.9(DL+FP) - %.1f(OMG)EL %s+ (SFAC)%s - (SPC)(SDS)DL"), dEL, strLSP, strPS);
            Set_LCB(nActive, strDesc, dDLm9,cDL, dDLm9,cCSD, 0.9,cFP,-dEL,cEL,  dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
            
            strDesc.Format(_T("0.9(DL+FP) + %.1f(SUF)(OMG)ESP %s+ (SFAC)%s - (SPC)(SDS)DL"), dEL, strLSP, strPS);
            Set_LCB(nActive, strDesc, dDLm9,cDL, dDLm9,cCSD, 0.9,cFP, dEL,cESP, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
            
            strDesc.Format(_T("0.9(DL+FP) - %.1f(SUF)(OMG)ESP %s+ (SFAC)%s - (SPC)(SDS)DL"), dEL, strLSP, strPS);
            Set_LCB(nActive, strDesc, dDLm9,cDL, dDLm9,cCSD, 0.9,cFP,-dEL,cESP, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
        }
    }
}

void CLoadCombCtrl::Make_SubComb_EQ9_1_ACI318_25(int nA, BOOL bStageCS, double dPSS, 
                                                 CombBase* cDL, CombBase* cCSD, CombBase* cFP, CombBase* cPSorTs, 
                                                 BOOL bSlcmSpecial, BOOL bSlcmVertical)
{
    // (5.3.1a) U = 1.4D : (See ACI318-25, Table 5.3.1)
    int nActive = GetActiveIndex(nA, bSlcmSpecial, bSlcmVertical);

    CString strPS   = bStageCS? _T("TS") : _T("PS");
    CString strDesc = _T("");

    strDesc.Format(_T("1.4(DL+FP) + (SFAC)%s"), strPS);
    Set_LCB(nActive, strDesc, 1.4,cDL, 1.4,cCSD, 1.4,cFP, dPSS,cPSorTs);
}

void CLoadCombCtrl::Make_SubComb_EQ9_2_ACI318_25(int nA, BOOL bStageCS, double dPSS,
                                                 CombBase* cDL, CombBase* cCSD, CombBase* cFP, CombBase* cLL, CombBase* cCSL, CombBase* cIL,
                                                 CombBase* cEPH, CombBase* cWP, CombBase* cLR, CombBase* cSL, CombBase* cRL, CombBase* cPSorTs, 
                                                 BOOL bSlcmSpecial, BOOL bSlcmVertical)
{
    // (5.3.1b) U = 1.2D+1.6L+(0.5Lr or 0.3S or 0.5R).
    int nActive = GetActiveIndex(nA, bSlcmSpecial, bSlcmVertical);

    CString strPS   = bStageCS? _T("TS") : _T("PS");
    CString strDesc = _T("");  

    double dSP = 0.0;
    CString strLSP  = _T("");
    if ( IsConsiderLateralSoil(cEPH, cWP) )
    {
        dSP = m_dLateralSoilFactor;
        strLSP = _T("+ (LSPF)(EH+WP) ");
    }

    // In case of m_bLateralSoil==FALSE, Set m_dLateralSoilFactor=0.0 in Initialize();
    if(!cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist())
    {
        strDesc.Format(_T("1.2(DL+FP) + 1.6(LL+IL) %s+ (SFAC)%s"), strLSP, strPS);    
        Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, 1.6,cLL, 1.6,cCSL, 1.6,cIL, dSP,cEPH, dSP,cWP, dPSS,cPSorTs);
    }
    else
    {
        CString strCaseLR[3] = { _T("LR"), _T("SL"), _T("RL") };
		double  dFactor[3]   = {0.5, 0.3, 0.5}; // Factors for LR, SL, RL
        CombBase* cLoadLR[3] = { cLR, cSL, cRL };

        for(int i=0; i<3; i++)
        {
            strDesc.Format(_T("1.2(DL+FP) + 1.6(LL+IL) %s+ %.1f%s+ (SFAC)%s"), strLSP, dFactor[i], strCaseLR[i], strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, 1.6,cLL, 1.6,cCSL, 1.6,cIL, dSP,cEPH, dSP,cWP, dFactor[i],cLoadLR[i], dPSS,cPSorTs);
        }
    }
}

void CLoadCombCtrl::Make_SubComb_EQ9_3_ACI318_25(int nA, BOOL bStageCS, BOOL bExistLL, double dPSS,
                                                 CombBase* cDL, CombBase* cCSD, CombBase* cFP,CombBase* cLL, CombBase* cCSL, CombBase* cIL,
                                                 CombBase* cLR, CombBase* cSL, CombBase* cRL, CombBase* cWL, CombBase* cPSorTs, 
                                                 BOOL bSlcmSpecial, BOOL bSlcmVertical)
{
    // (5.3.1c) U = 1.2D + (1.6Lr or 1.0S or 1.6R) + (1.0L or 0.5W)

    // Strength : 1.2D + (1.6Lr or 1.0S or 1.6R) + (1.0L or 0.5W).
    // Service  : 1.2D + (1.6Lr or 1.0S or 1.6R) + (1.0L or 0.8W).
    int nActive = GetActiveIndex(nA, bSlcmSpecial, bSlcmVertical);

    CString strPS   = bStageCS? _T("TS") : _T("PS");
    CString strDesc = _T("");

    double dWL = m_nWindLoadLevel==D_LOAD_LEVEL_STRN? 0.5 : 0.8;

    CString strCaseLR[3] = { _T("LR"), _T("SL"), _T("RL") };
	double  dFactor[3]   = {1.6, 1.0, 1.6}; // Factors for LR, SL, RL
    CombBase* cLoadLR[3] = { cLR, cSL, cRL };

    if(!bExistLL && !cWL->IsExist()) //1.2D + 1.6(LR or S or R).
    {
        for(int i=0; i<3; i++)
        {
            strDesc.Format(_T("1.2(DL+FP) + %.1f%s + (SFAC)%s"), dFactor[i], strCaseLR[i], strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, dFactor[i],cLoadLR[i], dPSS,cPSorTs);
        }
    }
    else
    {
        for(int i=0; i<3; i++)
        {
            strDesc.Format(_T("1.2(DL+FP) + %.1f%s + 1.0(LL+IL) + (SFAC)%s"), dFactor[i], strCaseLR[i], strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, dFactor[i],cLoadLR[i], 1.0,cLL, 1.0,cCSL, 1.0,cIL, dPSS,cPSorTs);

            strDesc.Format(_T("1.2(DL+FP) + %.1f%s + %.1fWL + (SFAC)%s"), dFactor[i], strCaseLR[i], dWL, strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, dFactor[i],cLoadLR[i], dWL,cWL, dPSS,cPSorTs);
            strDesc.Format(_T("1.2(DL+FP) + %.1f%s - %.1fWL + (SFAC)%s"), dFactor[i], strCaseLR[i], dWL, strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, dFactor[i],cLoadLR[i],-dWL,cWL, dPSS,cPSorTs);
        }
    }
}

void CLoadCombCtrl::Make_SubComb_EQ9_4_ACI318_25(int nA, BOOL bStageCS, BOOL bExistLL, double dPSS,
                                                 CombBase* cDL, CombBase* cCSD, CombBase* cFP, CombBase* cLL, CombBase* cCSL, CombBase* cIL,
                                                 CombBase* cLR, CombBase* cSL, CombBase* cRL, CombBase* cWL, CombBase* cPSorTs, 
                                                 BOOL bSlcmSpecial, BOOL bSlcmVertical)
{
    // (5.3.1d) U = 1.2D + 1.0W + 1.0L + (0.5Lr or 0.3S or 0.5R)

    // Strength : 1.2D + 1.0W + 1.0L + (0.5Lr or 0.3S or 0.5R)
    // Service  : 1.2D + 1.6W + 1.0L + (0.5Lr or 0.3S or 0.5R)
    int nActive = GetActiveIndex(nA, bSlcmSpecial, bSlcmVertical);

    CString strPS   = bStageCS? _T("TS") : _T("PS");
    CString strDesc = _T("");

    double dWL = m_nWindLoadLevel==D_LOAD_LEVEL_STRN? 1.0 : 1.6;

    BOOL bExistLRSeries = !cLR->IsExist() && !cSL->IsExist() && !cRL->IsExist()? FALSE : TRUE;
    if(bExistLRSeries)
    {
        CString strCaseLR[3] = { _T("LR"), _T("SL"), _T("RL") };
		double  dFactor[3]   = {0.5, 0.3, 0.5}; // Factors for LR, SL, RL
        CombBase* cLoadLR[3] = { cLR, cSL, cRL };

        if(bExistLL)
        {
            for(int i=0; i<3; ++i)
            {
                strDesc.Format(_T("1.2(DL+FP) + %.1fWL + 1.0(LL+IL) + %.1f%s + (SFAC)%s"), dWL, dFactor[i], strCaseLR[i], strPS); 
                Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, dWL,cWL, 1.0,cLL, 1.0,cCSL, 1.0,cIL, dFactor[i],cLoadLR[i], dPSS,cPSorTs);

                strDesc.Format(_T("1.2(DL+FP) - %.1fWL + 1.0(LL+IL) + %.1f%s + (SFAC)%s"), dWL, dFactor[i], strCaseLR[i], strPS); 
                Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP,-dWL,cWL, 1.0,cLL, 1.0,cCSL, 1.0,cIL, dFactor[i],cLoadLR[i], dPSS,cPSorTs);
            }
        }
        else
        {
            for(int i=0; i<3; ++i)
            {
                strDesc.Format(_T("1.2(DL+FP) + %.1fWL + %.1f%s + (SFAC)%s"), dWL, dFactor[i], strCaseLR[i], strPS);
                Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, dWL,cWL, dFactor[i],cLoadLR[i], dPSS,cPSorTs);

                strDesc.Format(_T("1.2(DL+FP) - %.1fWL + %.1f%s + (SFAC)%s"), dWL, dFactor[i], strCaseLR[i], strPS);
                Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP,-dWL,cWL, dFactor[i],cLoadLR[i], dPSS,cPSorTs);
            }
        }
    }
    else
    {
        if(bExistLL)
        {
            strDesc.Format(_T("1.2(DL+FP) + %.1fWL + 1.0(LL+IL) + (SFAC)%s"), dWL, strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, dWL,cWL, 1.0,cLL, 1.0,cCSL, 1.0,cIL, dPSS,cPSorTs);
            strDesc.Format(_T("1.2(DL+FP) - %.1fWL + 1.0(LL+IL) + (SFAC)%s"), dWL, strPS); 
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP,-dWL,cWL, 1.0,cLL, 1.0,cCSL, 1.0,cIL, dPSS,cPSorTs);
        }
        else
        {
            strDesc.Format(_T("1.2(DL+FP) + %.1fWL + (SFAC)%s"), dWL, strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, dWL,cWL, dPSS,cPSorTs);
            strDesc.Format(_T("1.2(DL+FP) - %.1fWL + (SFAC)%s"), dWL, strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP,-dWL,cWL, dPSS,cPSorTs);
        }    
    }
}

