                strDesc.Format(_T("1.2(DL+FP) - %.1f(SUF)ESP + 1.0(LL+IL) + (SFAC)%s"), dEL, strPS); Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP,-dEL,cESP, 1.0,cLL, 1.0,cCSL, 1.0,cIL, dPSS,cPSorTs);
