                strDesc.Format(_T("1.2(DL+FP) - %.1f(OMG)EL + 1.0(LL+IL) + (SFAC)%s + (SPC)(SDS)DL"), dEL, strPS);       Set_LCB(nActive, strDesc, dDLp12,cDL, dDLp12,cCSD, 1.2,cFP,-dEL,cEL,  1.0,cLL, 1.0,cCSL, 1.0,cIL, dPSS,cPSorTs);
                strDesc.Format(_T("1.2(DL+FP) + %.1f(SUF)(OMG)ESP + 1.0(LL+IL) + (SFAC)%s + (SPC)(SDS)DL"), dEL, strPS); Set_LCB(nActive, strDesc, dDLp12,cDL, dDLp12,cCSD, 1.2,cFP, dEL,cESP, 1.0,cLL, 1.0,cCSL, 1.0,cIL, dPSS,cPSorTs);
