void CLoadCombCtrl::Make_SubComb_EQ9_2_ACI318_05(int nA, BOOL bStageCS, double dPSS,
                                                 CombBase* cDL, CombBase* cCSD, CombBase* cFP, CombBase* cTL, CombBase* cCR, CombBase* cSH, CombBase* cCSC, CombBase* cCSS,
                                                 CombBase* cLL, CombBase* cCSL, CombBase* cEP, CombBase* cWP,
                                                 CombBase* cLR, CombBase* cSL,  CombBase* cRL, CombBase* cPSorTs, 
                                                 BOOL bSlcmSpecial, BOOL bSlcmVertical)
{
    //1.2(D+F+T) +1.6(L+H) + 0.5(LR or S or R)
    int nActive = GetActiveIndex(nA, bSlcmSpecial, bSlcmVertical);

    CString strPS   = bStageCS? _T("TS") : _T("PS");
    CString strDesc = _T("");

    BOOL bExistLR = IsExistCombBase(cLR);
    BOOL bExistSL = IsExistCombBase(cSL);
    BOOL bExistRL = IsExistCombBase(cRL);

    if(!bExistLR && !bExistSL && !bExistRL)
    {
        strDesc.Format(_T("1.2(DL+FP+(TL+CR+SH)) + 1.6(LL+(EP+WP)) + (SFAC)%s"), strPS);
        Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, 1.2,cTL, 1.2,cCR, 1.2,cSH, 1.2,cCSC, 1.2,cCSS, 1.6,cLL, 1.6,cCSL, 1.6,cEP, 1.6,cWP, dPSS,cPSorTs);    
    }
    else
    {
        CString strCaseLR[3] = { _T("LR"), _T("SL"), _T("RL") };
        CombBase* cLoadLR[3] = { cLR, cSL, cRL };

        for(int i=0; i<3; i++)
        {
            if (cLoadLR[i]==nullptr || !cLoadLR[i]->IsExist()) continue;
            strDesc.Format(_T("1.2(DL+FP+(TL+CR+SH)) + 1.6(LL+(EP+WP)) + 0.5%s + (SFAC)%s"), strCaseLR[i], strPS);
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.2,cFP, 1.2,cTL, 1.2,cCR, 1.2,cSH, 1.2,cCSC, 1.2,cCSS, 1.6,cLL, 1.6,cCSL, 1.6,cEP, 1.6,cWP, 0.5,cLoadLR[i], dPSS,cPSorTs);    
        }
    }
}

void CLoadCombCtrl::Make_SubComb_EQ9_3_ACI318_05(int nA, BOOL bStageCS, BOOL bExistLL, double dPSS,
                                                 CombBase* cDL, CombBase* cCSD, CombBase* cLL, CombBase* cCSL, CombBase* cWL,                                                 
                                                 CombBase* cLR, CombBase* cSL,  CombBase* cRL, CombBase* cPSorTs, 
                                                 BOOL bSlcmSpecial, BOOL bSlcmVertical)
{
    //1.2D + 1.6(LR or S or R) + (1.0L or 0.8W)
    int nActive = GetActiveIndex(nA, bSlcmSpecial, bSlcmVertical);

    CString strPS   = bStageCS? _T("TS") : _T("PS");
    CString strDesc = _T("");

    CString strCaseLR[3] = { _T("LR"), _T("SL"), _T("RL") };
    CombBase* cLoadLR[3] = { cLR, cSL, cRL };

    if(!bExistLL && !cWL->IsExist())
    {
        for(int i=0; i<3; i++)
        {
            if (cLoadLR[i]==nullptr || !cLoadLR[i]->IsExist()) continue;

            strDesc.Format(_T("1.2DL + 1.6%s + (SFAC)%s"), strCaseLR[i], strPS); 
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.6,cLoadLR[i], dPSS,cPSorTs);
        }
    }
    else
    {
        for(int i=0; i<3; i++)
        {
            if (!IsExistCombBase(cLoadLR[i])) continue;

            strDesc.Format(_T("1.2DL + 1.6%s + 1.0LL + (SFAC)%s"), strCaseLR[i], strPS); 
            Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.6,cLoadLR[i], 1.0,cLL, 1.0,cCSL,dPSS,cPSorTs);

            if(m_strCurrentCode == _T("NSR-10"))
            {
                strDesc.Format(_T("1.2DL + 1.6%s + 0.5WL + (SFAC)%s"), strCaseLR[i], strPS);
                Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.6,cLoadLR[i], 0.5,cWL, dPSS,cPSorTs);

                strDesc.Format(_T("1.2DL + 1.6%s - 0.5WL + (SFAC)%s"), strCaseLR[i], strPS);
                Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.6,cLoadLR[i],-0.5,cWL, dPSS,cPSorTs);
            }
            else
            {
                strDesc.Format(_T("1.2DL + 1.6%s + 0.8WL + (SFAC)%s"), strCaseLR[i], strPS);
                Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.6,cLoadLR[i], 0.8,cWL, dPSS,cPSorTs);

                strDesc.Format(_T("1.2DL + 1.6%s - 0.8WL + (SFAC)%s"), strCaseLR[i], strPS);
                Set_LCB(nActive, strDesc, 1.2,cDL, 1.2,cCSD, 1.6,cLoadLR[i],-0.8,cWL, dPSS,cPSorTs);
            }
        }
    }
}

