void CLoadCombCtrl::Make_SubComb_EQ5_AISC_ASD05(int nA, BOOL bExistWPEP, 
                                                CombBase* cDL,  CombBase* cLL,  CombBase* cLR,  CombBase* cWL,  CombBase* cEL, 
                                                CombBase* cSL,  CombBase* cRL, 	CombBase* cWP,  CombBase* cEP,  CombBase* cFP,  
                                                CombBase* cPS,  CombBase* cESP, CombBase* cCSD, CombBase* cEPH, CombBase* cEPV)

{
    // [ASCE7-02, 2.4.1.5] D + H + F + (W or 0.7E).  
    if(!bExistWPEP)
    {    
        if(!cFP->IsExist())
        {
            Set_LCB(nA, _T("DL + WL + PS")   , 1.0,cDL, 1.0,cCSD,  1.0,cWL, 1.0,cPS);
            Set_LCB(nA, _T("DL - WL + PS")   , 1.0,cDL, 1.0,cCSD, -1.0,cWL, 1.0,cPS);
            Set_LCB(nA, _T("DL + 0.7EL + PS")   , 1.0,cDL, 1.0,cCSD,  0.7,cEL, 1.0,cPS);
            Set_LCB(nA, _T("DL - 0.7EL + PS")   , 1.0,cDL, 1.0,cCSD, -0.7,cEL, 1.0,cPS);  
            Set_LCB(nA, _T("DL + 0.7(SUF)ESP + PS"), 1.0,cDL, 1.0,cCSD,  0.7,cESP,1.0,cPS);
            Set_LCB(nA, _T("DL - 0.7(SUF)ESP + PS"), 1.0,cDL, 1.0,cCSD, -0.7,cESP,1.0,cPS);
        }
        else
        {
            Set_LCB(nA, _T("DL + FP + WL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cFP, 1.0,cWL, 1.0,cPS);
            Set_LCB(nA, _T("DL + FP - WL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cFP,-1.0,cWL, 1.0,cPS);
            Set_LCB(nA, _T("DL + FP + 0.7EL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cFP, 0.7,cEL, 1.0,cPS);
            Set_LCB(nA, _T("DL + FP - 0.7EL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cFP,-0.7,cEL, 1.0,cPS);  
            Set_LCB(nA, _T("DL + FP + 0.7(SUF)ESP + PS"), 1.0,cDL, 1.0,cCSD, 1.0,cFP, 0.7,cESP,1.0,cPS);
            Set_LCB(nA, _T("DL + FP - 0.7(SUF)ESP + PS"), 1.0,cDL, 1.0,cCSD, 1.0,cFP,-0.7,cESP,1.0,cPS);
        }
    }
    else
    {
        if(!cFP->IsExist())
        {
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + WL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP,  1.0,cWL, 1.0,cPS);
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) - WL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, -1.0,cWL, 1.0,cPS);
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + 0.7EL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP,  0.7,cEL, 1.0,cPS);
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) - 0.7EL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, -0.7,cEL, 1.0,cPS);  
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + 0.7(SUF)ESP + PS"), 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP,  0.7,cESP,1.0,cPS);
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) - 0.7(SUF)ESP + PS"), 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, -0.7,cESP,1.0,cPS);
        }
        else
        {
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + FP + WL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, 1.0,cFP, 1.0,cWL, 1.0,cPS);
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + FP - WL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, 1.0,cFP,-1.0,cWL, 1.0,cPS);
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + FP + 0.7EL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, 1.0,cFP, 0.7,cEL, 1.0,cPS);
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + FP - 0.7EL + PS")   , 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, 1.0,cFP,-0.7,cEL, 1.0,cPS);  
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + FP + 0.7(SUF)ESP + PS"), 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, 1.0,cFP, 0.7,cESP,1.0,cPS);
            Set_LCB(nA, _T("DL + (EP+EV+EH+WP) + FP - 0.7(SUF)ESP + PS"), 1.0,cDL, 1.0,cCSD, 1.0,cEP, 1.0,cEPV, 1.0,cEPH, 1.0,cWP, 1.0,cFP,-0.7,cESP,1.0,cPS);
        }
    }
}

